const html: string = "<div>\n        <p>\n          <span>1. Əsas müddəalar&#160;</span>\n        </p>\n        <p>\n          <span>1.1. Mərclər yalnız 21 yaşdan yuxarı şəxslərdən qəbul edilir\n            yaşında. Müştərinin yurisdiksiyasının qanunvericiliyi müəyyən edərsə\n            qumarda iştirak üçün daha yüksək minimum yaş, daha yüksək yaş tətbiq edilir. 21 yaşdan kiçik bir şəxs tərəfindən qeydiyyat, depozit və ya mərc\n            yaş (və ya Müştərinin yurisdiksiyasında qanunla tələb olunan yaşa çatmamış)\n            Qaydaların kobud şəkildə pozulmasıdır: Şirkət bağlamaq hüququna malikdir\n            hesaba girin, mərcləri ləğv edin və geri qaytarılmadan vəsait tutun.&#160;</span>\n        </p>\n        <p>\n          <span>\n            1.2. Mərclər yalnız qaydalarla razılaşan şəxslərdən qəbul edilir,\n            daha sonra bukmeker kontoru tərəfindən müəyyən edilmişdir (Imba.bet). İstənilən mərc müştərinin bu qaydaları bildiyinin və onlarla razılaşdığının təsdiqidir. İdarə\n            bu Qaydaların pozulması ilə qoyulmuş mərcləri etibarsız hesab etmək hüququna malikdir.\n            Rəhbərlik mərclərin dəqiq nə vaxt məlum olması və ya sonradan müəyyən edilməsi ilə bağlı heç bir məsuliyyət daşımır\n            Qaydaları pozmaqla həyata keçirilmişdir.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            1.3. Rəhbərliyin mərcləri qəbul etməmək hüququ var\n            bunlara əməl etməyən şəxslər\n          </span>\n        </p>\n        <p>\n          <span>\n            1.4. Qəbul edilməsi ilə bağlı fırıldaqçılıq fəaliyyəti aşkar edildikdə\n            bahis və ya maliyyə əməliyyatları idarə etmək hüququna malikdir\n            mərcləri etibarsız saymaqla, hesabları bağlamaqla bu cür hərəkətləri dayandırın\n            pul qalığının qaytarılması və hüquq-mühafizə orqanlarına müraciət edilməsi\n            dələduzluq əməllərinin törədilməsi ilə bağlı qurumlar.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            1.5. Qarşıda (hadisədən sonra) mərclər aşkar edildikdə, hesab\n            geri qaytarılmadan bloklanıb.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            1.6. Müştəri tərəfindən etibarlı mərclərə mərc edildiyi halda — hesab\n            geri qaytarılmadan bloklanıb.\n          </span>\n        </p>\n        <p>\n          <span>\n            1.7. Mübahisəli məsələlərlə bağlı iddialar 10 gün müddətində qəbul edilir\n            yazılı ərizə əsasında tədbir başa çatdıqdan sonra.\n            Bütün mübahisəli vəziyyətlər üzrə yekun qərar verilir\n            administrasiya tərəfindən.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            1.8. Bu qaydalar və onlara edilən əlavə və dəyişikliklər 2010-cu il tarixində qüvvəyə minir\n            saytda dərc tarixi və bütün mərclərə və hərəkətlərə müraciət edin,\n            bildiklərindən asılı olmayaraq dərc edildiyi tarixdən etibarən edilir\n            müştərilərə qaydaların bu versiyasının qüvvəyə minməsi haqqında\n            ya yox. Bütün əvvəlki qaydalar artıq nəzərə alınmır\n          </span>\n        </p>\n        <p>\n          <span>\n            1.9.Şirkət oyun hesabını bağlamaq hüququnu özündə saxlayır,\n            mərcləri və balansı ləğv etmək, əgər Şirkət yaradılmışdırsa\n            ki: a) mərc edən zaman mərc edənin məlumatı var idi\n            hadisənin nəticəsi (sabit uyğunluq); b) Bettor birbaşa iştirakçıdır\n            matçda (idmançılar, hakimlər, məşqçilər və s.) və ya bir şəxs\n            onunla razılaşma əsasında fəaliyyət göstərmək; c) bir qrup Bettors tərəfindən bağlanan mərc\n            həddi aşmaq məqsədilə konsert (sindikat) halında fəaliyyət göstərmək\n            Şirkət tərəfindən yaradılmışdır; d) bir Bettorun bir neçə oyun hesabı var;\n            e) mərc iştirakçısı xüsusi proqram təminatından istifadə etməkdə şübhəli bilinir\n            və ya mərc prosesinin avtomatlaşdırılmasına imkan verən texniki vasitələr; f)\n            məlumat əldə etmək və ya məhdudiyyətləri keçmək üçün hər hansı vicdansız yollar\n            şirkət tərəfindən yaradılmışdır; g) inanmaq üçün əsaslar var\n            oyun hesabı bahis və ya digər əlaqəli fəaliyyətlər üçün istifadə edilmir\n            oyunlar. Təsvir edilən vəziyyətlərdə Bettor hesabının balansı\n            yuxarıda yenidən hesablanmalı və fərdi olaraq nəzərdən keçirilməlidir.\n            \n            \n          </span>\n        </p>\n        <p>\n          <span>2. Əmanətinizin doldurulması və uduşların alınması</span>\n        </p>\n        <p>\n          <span>\n            2.1. Mərclər xətt əsasında qəbul edilir - qarşıdan gələn hadisələrin siyahısı\n            bukmeker kontorunun təklif etdiyi qiymətlərlə - qazanma əmsalı. Sitatlar ola bilər\n            hər hansı bir mərcdən sonra dəyişiklik, lakin əvvəllər qoyulmuş mərclərin şərtləri\n            eyni qalsın. Bahis etməzdən əvvəl oyunçular hər şeyi öyrənməlidirlər\n            xəttində dəyişikliklər.\n          </span>\n        </p>\n        <p>\n          <span>\n            2.2. Yerləşdirilmiş mərclər, onları serverə yerləşdirdikdən və qəbul etdikdən sonra\n            Onlara oyunçudan mərcin qəbul edilməsi haqqında mesaj və\n            kupon nömrəsi, istək üzərinə oyunçular ləğv edilə bilməz\n            və ya düzəliş, lakin bunların 4.5-ci bəndinə uyğun olaraq\n            Qaydalar rəhbərlik tərəfindən ləğv edilə bilər. Əlaqələri qırın və ya\n            digər rabitə xətaları əgər mərcdən imtina etmək üçün əsas deyil\n            bahis serverdə qeydə alınıb. Məzənnələr yalnız olmayan bir məbləğdə qəbul edilir\n            müştərinin cari hesab balansını aşması. Qeydiyyatdan keçdikdən sonra\n            mərc, mərc məbləği hesablardan silinir. Mərclər hesablandıqdan sonra,\n            uduş məbləği\n          </span>\n        </p>\n        <p>\n          <span>\n            2.3. Aşağıdakı mərc növləri fərqləndirilir: \"tək\",\n            &quot;ekspress&quot; və \"sistem\". Tək mərc - Bu mərc\n            yalnız bir hadisənin nəticəsini proqnozlaşdırmaq lazımdır. Tək mərclər qəbul edilir\n            hər hansı bir hadisədə. Tək mərclərdə uduş mərc məbləğinin vurulmasına bərabərdir\n            qalibiyyət əmsalı ilə. Express - proqnozlaşdırmaq lazım olan bir mərc\n            eyni anda birdən çox hadisənin nəticəsi. Ən azı bir hadisə\n            ekspress mərcdə səhv təxmin edilir, bütün ekspress mərc\n            itirilmiş hesab olunur. B ekspresi hadisələrin istənilən kombinasiyasını əhatə edə bilər\n            hər hansı bir idman növü. Siz ekspress-ə asılı hadisələri daxil edə bilməzsiniz: eyni\n            hadisə bir dəfədən çox ekspressdə iştirak edə bilməz, əlaqələndirilə bilməz\n            ekspress mərcdə matçın nəticəsi və iştirak edən komandaya mərclər\n            onda uyğunluq (məsələn: növbəti mərhələyə keçid və s.). Ekspres varsa\n            asılı hadisələr olduğu ortaya çıxdı, sonra yalnız hesablama məqsədləri üçün\n            ən yüksək əmsalı olanlardan biridir. Ekspres mərc uduşları hesablanır\n            ekspressə daxil olan bütün hadisələrin uduş əmsalını vurmaqla.\n            Ekspres mərclər üzrə uduşlar vurulan mərc məbləğinə bərabərdir\n            ekspres mərcin uduş əmsalı ilə. Uduş əmsalı\n            limitsiz. Sistem - a-nın ekspress mərclərinin tam kombinasiyası\n            əvvəlcədən müəyyən edilmiş sayda hadisələrdən verilən ölçü (maksimum sayı\n            sistemdəki hadisələrin sayı 16). Sistemdəki hər bir birləşmə\n            ayrıca ekspress kimi hesablanır.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            2.4. Minimum tarifi rəhbərlik müəyyən edir. Maksimum\n            xətt üzrə bir mərc üçün ödəniş 3 milyon rubl, canlıda - 1\n            milyon rubl Digər valyutalarda mərclər üçün maksimum ödəniş müəyyən edilir\n            ofis məzənnəsi ilə yenidən hesablanır. Bəzi kateqoriyalar üçün\n            maksimum uduşlar üçün oyunlar və mərclər üçün xüsusi limitlər müəyyən edilə bilər,\n            bu Qaydaların müvafiq hissələrində göstərilən.\n          </span>\n        </p>\n        <p>\n          <span>\n            2.5. Rəhbərliyin maksimum dərəcəsini məhdudlaşdırmaq hüququ var\n            fərdi hadisələr, həmçinin maksimum dərəcəsi məhdudlaşdırmaq və ya artırmaq\n            bildiriş və ya izahat olmadan konkret müştəriyə\n            səbəblər. Rəhbərliyin məhdudlaşdırmaq və ya imtina etmək hüququ var\n            göstərilən xidmətlərə və ya xidmətlərə çıxışda xüsusi müştərilər\n            bildirişlər və izahatlar olmadan\n          </span>\n        </p>\n        <p>\n          <span>\n            2.6. Mərclər tədbir başlamazdan əvvəl qəbul edilir. halda\n            nədənsə təklif faktiki sonra yerləşdirildi\n            hadisələrə başladıqda belə mərc etibarsız sayılır. İstisna makiyajı\n            “Canlı” hadisələrə mərclər, yəni matçın gedişinə mərclər. Belə\n            mərclər matçın sonuna qədər edildiyi təqdirdə etibarlı sayılır.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            2.7. Administrasiya “Canlı” mərcini ləğv etmək hüququnu özündə saxlayır\n            Əgər Administrasiya mərc edərkən müştərinin olduğundan şübhələnirsə\n            nisbətində göstərilən hadisənin nəticəsi haqqında məlumat vardı. In\n            bu halda İdarə səbəbini sübut etməyə borclu deyil\n            belə şübhələrin ortaya çıxması&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            2.8. Əgər “Canlı” yerləşdirmə prosesi zamanı müştəriyə mərc edirsə\n            əmsalların və ya mərc parametrlərinin dəyişməsi ilə razılaşdırılmışdır (handikap, cəmi,\n            və s.), onda hadisənin hesabı dəyişsə belə, mərc qəbul edilir\n            mərc qeydə alınan vaxta qədər.\n          </span>\n        </p>\n        <p>\n          <span>3. &#160; mərc hesablanmasının xüsusiyyətləri</span>\n        </p>\n        <p>\n          <span>\n            3.1. Tədbirin başlanma tarixi və vaxtı\n            xətt informativ xarakter daşıyır. Səhv göstərilib\n            tarix, vaxt və ya əlavə məlumat (turnirin statusu və ya mərhələsi,\n            ilk matçın hesabı və s.) mərcin ləğvi üçün əsas deyil.\n            Əgər hadisə ilkin elan ediləndən əvvəl və ya gec baş vermişsə\n            tarix, nəticə etibarlı sayılır və mərclər nəzərə alınır\n            tədbir başlamazdan əvvəl edildiyi təqdirdə etibarlıdır. Təxirə salınması halında\n            3 və ya daha çox mərc günü ərzində başlamamış hadisə\n            qayıdırlar. Başlamamış bir hadisə daha az müddətə təxirə salınarsa\n            3 gündən çox müddətə tariflər qüvvədə qalır, ancaq idarənin haqqı var\n            gözləmədən mərcləri geri qaytarma qərarı qəbul etmək hüququ\n            Tədbirin sonunda hansı oyunçular haqqında rəsmi məlumat verilir\n            nəticələr. Əgər NBA, NHL MLB və ya NFL matçında iştirak etmədi\n            təyin edilmiş gündə tamamlanmadıqda, mərclər geri qaytarılır\n            tarixi olduğu hallar istisna olmaqla, dərhal ertəsi gün\n          </span>\n        </p>\n        <p>\n          <span>\n            3.2. Tədbirlər siyahısında birinci yer ilə göstərilir\n            matçın keçirildiyi sahədə olan komanda. halında a\n            Komandanın sahəsində keçirilən matçda ikinci sırada iştirak etdiyi göstərildi\n            hadisələrin siyahısı (bir şəhər və ya bölgənin komandalarının matçları istisna olmaqla),\n            bu matça mərc qaytarılır, ekspress mərclərdən isə qaytarılır\n            istisna olunur. Neytral meydanda matçın keçirilməsi əsas deyil\n            mərclərin ləğvi. Başlıq yarışlarında göstərildiyi təqdirdə sıra ilə\n            Turnirin keçirildiyi yerlə, idmançının və ya idmançının qeydinə icazə verilir\n            ev sahibi komanda birinci deyil.\n          </span>\n        </p>\n        <p>\n          <span>3.3. Kəsilən hadisələr: </span>\n        </p>\n        <p>\n          <span>\n            3.3.1. Hadisə kəsildiyi halda baş vermiş sayılır\n            və ən azı qaydalarla tənzimlənən oyunun müəyyən hissəsini oynamışdır\n            tam zaman. Bütövlükdə matça mərc etmək üçün belədir: futbol -\n            65 dəq. (əgər uyğunluq formatı standart deyilsə, onda 70 faiz\n            oyun vaxtı); basketbol - 35 dəq. (NBA və digərləri üçün\n            48 dəqiqəlik matçlarla turnirlər) və 28 dəq. ilə turnirlər üçün\n            40 dəqiqəlik matçlar; xokkey - 45 dəqiqə; Bandy - 60 dəq.; Amerika futbolu\n            - 50 dəq; beysbol - 5 vuruş; digər idman növləri - ən azı 70% oynayır\n            vaxt. İstisna dayanma anında xalların bərabər olması hallarıdır\n            reqlamentin heç-heçəyə icazə vermədiyi idman növləri üzrə matçlar (basketbol,\n            beysbol, Amerika futbolu və s.). Belə hallarda, bu\n            hadisə baş verməmiş hesab olunur. Əgər hadisə tanınırsa\n            uğursuz olduqda, \"Pass\" üzrə mərclər qaytarılır. Hadisə tanınsa\n            etibarlıdır, onda “Pass” üzrə mərclər aşağıdakılara uyğun olaraq hesablanır\n            oyunun dayandırıldığı anda faktiki hesab və a\n            bərabərlik mərcləri - geri qaytarılması. himayəsi altında keçirilən tədbirlərə görə\n            ən böyük beynəlxalq təşkilatlar (məsələn, FIFA və UEFA\n            futbolda), zaman hadisənin vaxtı haqqında məlumat tez\n            ictimai sahədə görünür. oyunun başa çatması (30 saata qədər),\n            rəhbərliyin qərarı ilə bütün mərclər hesablana bilər\n            yekun nəticəyə görə. Ayrı-ayrı hissələrinə mərclər üçün\n            matç (basketbolda dörddəbirlər, futbolda yarılar, xokkeydə dövrlər\n            və buna bənzər) əgər onlar kəsilibsə, onlar kimi sayılırlar\n            Ən az 70% oynanmışsa, oyun müddəti ilə tənzimlənir\n            bu hissənin uyğunluğu qaydaları. Keçən oyun vaxtının hesablanması tələb olunur\n            yalnız oynanan dəqiqələr və yuvarlaqlaşdırılmış fraksiyalar nəzərə alınmaqla\n            aşağı. Məsələn, xokkey matçı 14-cü dəqiqədə dayandırıldı\n            Bəzi periodlar isə 13 dəqiqə 20 saniyə oynandı. Bunda\n            halda 13 tam dəqiqə oynanılıb ki, bu da 65%, yəni daha azdır\n            70%. Buna görə də, bu dövr üçün mərclər ləğv edilməlidir.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.3.2. Tərifə daxil olmayan kəsilmiş hadisə\n            baş vermiş hadisə baş vermədiyi təqdirdə etibarsız sayıla bilər\n            3 saat ərzində oyunu bitirdi.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.3.3. Baş verməmiş kimi tanınan, kəsilmiş hadisələr üçün,\n            qaytarılması Bütün mərclər mərclərə tabedir, mərclər istisna olmaqla, nəticəsi\n            hadisənin dayandırılması zamanı unikal olaraq müəyyən edilir (üçün\n            məsələn, 1-ci qolu kim vuracaq, kart alacaq, orada\n            cəmi “bitdi” və s.). Fasilələrə məruz qalan hadisələr üçün\n            müqayisəli göstəricilərə mərclərin qeyd-şərtsiz qaytarılmasına\n          </span>\n        </p>\n        <p>\n          <span>\n            3.3.4 Baş vermiş kimi tanınan kəsilmiş hadisələr hesablanır\n            ümumi əsasda. Fasiləli matça mərclər (oyun, yarış\n            və ya s.), geri sayım başlamamış (məsələn, məqsəd\n            76-dan 90-a qədər matç 70-ci dəqiqədə kəsilirsə).\n            geri qaytarıla bilər. Başlanmış, lakin tamamlanmamış hadisələrə mərclər\n            (məsələn, 61-dən 75-ə qədər intervalda qol olacaqmı?\n            dəqiqələr matç dayandırılırsa\n          </span>\n        </p>\n        <p>\n          <span>\n            3.3.5 Müəyyən idman hesablamaları üçün əlavə funksiyalar mümkündür\n            dərəcələrin, əgər onlar qanunun müvafiq bəndlərində göstərilmişdirsə\n          </span>\n        </p>\n        <p>\n          <span>\n            3.4. Tamamlanmış hadisənin ilkin nəticəsi sonradan ləğv edilərsə\n            hər hansı bir səbəbdən, ləğv və tarifləri nəzərə alınmayacaq\n            ilkin (faktiki) nəticəyə uyğun olaraq ödənilməlidir. Nəticə\n            rəsmi protokollar və digər rəsmi şəxslər əsasında bəyan edilir\n            hadisə başa çatdıqdan dərhal sonra mənbə məlumat verir.\n            Rəsmi mənbələrdə nəticə olmadıqda, administrasiya\n            alternativ informasiya mənbələrindən, o cümlədən informasiyadan istifadə etmək hüququna malikdir\n            matçda öz təmsilçinizdən. Sətirdədirsə Adı\n            müsabiqənin mənbəsini aydın şəkildə göstərir (məsələn,\n            televiziya yayımı), o zaman müəyyən edilərkən prioritetə malikdir\n            nəticə. Əgər tədbir ertəsi gün kəsilib oynanılırsa\n            lap əvvəldən, sonra məskunlaşma məqsədləri üçün birinci\n            matç kəsilmiş hadisə sayılır və uyğun olaraq hesablanır\n            3.3-cü bənd\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5. Administrasiya mərci etibarsız elan etmək hüququna malikdir\n            hallarda:\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.1 Mərcləri qəbul edərkən kadr səhvləri və ya proqram təminatının nasazlığı\n            (əmsallarda aşkar yazı səhvləri, ehtimalların uyğunsuzluğu\n            müxtəlif vəzifələr və s.)\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.2 Qeyri-idman döyüşünün aşkar əlamətləri olduqda. halda\n            Fonbetdəki matçların qeyri-idman xarakteri ilə bağlı şübhələr yaranır\n            və ya beynəlxalq təşkilatlardan EWS-FIFA xəbərdarlığı ilə,\n            Federbet və Tennis Dürüstlük Vahidi idarəsi var\n            sağ əvvəllər şübhəli mərc edən Müştərinin mərclərini bloklayır\n            beynəlxalq təşkilatın rəyi və tanınması\n            idmana uyğun olmayan davranış faktı müəyyən edildikdə mərclər etibarsız sayılır\n            mübarizə. Rəhbərlik futbolçulara sübut təqdim etməyə borclu deyil\n            və nəticələr.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.3 Mərclərin qəbulu ilə bağlı fırıldaqçılıq fəaliyyətinin aşkar edilməsi və ya\n            əməliyyatlar, saxta sənədlərin təqdim edilməsi;\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.4 Başqasının hesabından oynama faktının təsdiqi\n            və ya şəxsi hesabınızdan istifadə ilə bağlı şübhələrin baş verməsi\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.5 Yoxlama prosedurundan keçməkdən imtina, o cümlədən\n            yenidən qeydiyyat faktının təsdiqi (o cümlədən\n            digər insanların şəxsi məlumatlarından, sənədlərindən, o cümlədən istifadə etməklə. boş və saxta).\n            \n          </span>\n        </p>\n        <p>\n          <span>3.5.6 Bu qaydaların pozulması ilə bağlı digər hallarda.</span>\n        </p>\n        <p>\n          <span>\n            3.6. Əgər mərc etibarsız elan edilərsə, bu mərcün geri qaytarılması və\n            əgər ekspress və ya sistemə daxil edilibsə, onda hesablama məqsədləri üçün\n            1 əmsalı ilə nəzərə alınır.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.7. Bütün cari nəticələr, oyun vaxtı, digər əlavə məlumatlar\n            saytda göstərilən məlumatlar yalnız istinad məlumatı kimi xidmət edir. İdarə\n            məlumatların düzgünlüyünü təmin etməyə çalışır, lakin məsuliyyət daşımır\n            bu məlumat əsasında edilən mərclərin nəticələri üçün.\n            Müştəriyə mərc hesablamalarının düzgünlüyünü yoxlamaq tövsiyə olunur,\n            canlı mərclər daxil olmaqla, rəsmi məlumat mənbələrindən istifadə edin (rəsmi\n            idman tədbirlərinin təşkilatçıları).\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            3.8. Eyni vaxtda mərclər və mövcud olanları keçməyə imkan verən mərclər\n            bir və eyni nəticə üçün maksimum mərc və ya ödəmə məbləğləri\n            bir qrup şəxsdən (oyunçuların sindikatı və s.) icazə verilmir.\n            Not Eyni kombinasiyaya təkrar mərclərin qoyulmasına icazə verilmir\n            ümumi potensial ödəniş maksimumdan artıq olduqda nəticələr. İdarə\n            belə tarifləri etibarsız elan etmək hüququna malikdir.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            3.9. Hesab və ya digər matç parametrlərində hər hansı dəyişiklik səbəb olur\n            rəsmi hakimin qərarı (məsələn, qolun vaxtından əvvəl rədd edilməsi\n            ofsayta, videoya baxıldıqdan, ləğv edildikdən və ya yenidən baxıldıqdan sonra\n            tennis nöqtəsi, voleybol və s.) və ya iştirakçıların qarşılıqlı razılığı\n            (məsələn, meydandan qovulduqdan sonra bərabər güclə oynamaq və s.)\n            ləğv etmək üçün səbəb deyil\n          </span>\n        </p>\n        <p>\n          <span>\n            3.10. Presedent olmadan mübahisəli vəziyyətlərdə, final\n            qərar daha sonra bukmeker kontoru tərəfindən qəbul edilir (Imba.bet).\n          </span>\n        </p>\n        <p>\n          <span>4. Əsas mərc növləri&#160;</span>\n        </p>\n        <p>\n          <span>\n            4.1. Həqiqi nəticəyə mərclər. Qəbul etmədən matçlara mərc edə bilərsiniz\n            müvafiq əmsallar göstərildikdə, handikap nəzərə alınmaqla\n            (birinci mövqelərdə - birinci komandanı qazanmağa görə (\"1\"), üçün\n            ikinci mövqe - heç-heçə \"X\" üçün əmsal, üçüncü mövqedə\n            - ikinci komandanın qalib gəlməsi əmsalları (\"2\"). Bu halda,\n            mərcin nəticəsi matçın faktiki nəticəsidir. Həm də sən\n            1-ci komandanın uduzmayacağına mərc edə bilər (&quot;1X&quot;),\n            2-ci komanda uduzmayacaq (&quot;X2&quot;) və ya heç-heçə (&quot;12&quot;) olmayacaq.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            4.2. Qarşılaşmada hər komandanın qalibiyyəti üzərinə qoyulan mərclər\n            handikap (handikap) hesaba alınır. Handikap tərəfindən müəyyən edilir\n            bukmeyker və müsbət, mənfi və ya sıfıra bərabər ola bilər. Kimə\n            tərəfindən vurulan faktiki qollara mərcin nəticəsini müəyyənləşdirin\n            mərc edilən komanda, o, götürülür (handikap varsa\n            mənfi) və ya seçilmiş komanda üçün handikap əlavə edilir (əgər\n            handikap müsbətdir) (ikinci komanda üçün handikap deyil\n            nəzərə alınır). Əgər sonra matçın nəticəsi varsa\n            seçilmiş komandanın xeyrinə, o zaman mərc qazanılmış sayılır. halda\n            heç-heçə - mərc qaytarır. Məsələn, əgər birinci əmr\n            mənfi handikap \"-1\" təyin olundu və matç başa çatdı: a) hesabla\n            0:0, uduzmuş mərc; b) 1:0 hesabı ilə mərc qaytarılır; c) ilə\n            hesab 2:0, mərc qalib gəlir. A müsbət handikap təyin olunarsa\n            &quot;+0,5&quot; və matç başa çatdı a) 0:1 hesabı ilə,\n            itirilmiş bahis; b) 0:0 və ya 1:0 hesabı ilə mərc qalib gəlir.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.3. Asiya handikapı. Handikap (handikap) daxil olmaqla qələbə və ya total mərc,\n            0,25-ə qat (lakin 0,5-ə deyil). Bu mərc hesablanıb\n            eyni olan məbləğin yarısı məbləğində iki mərc kimi\n            əmsallar və &quot;handikap üçün” və ən yaxın dəyərləri ilə\n            “müntəzəm cəmlər” (tam və ya 0,5-in qatları). Bu cür hadisələr\n            sətir “Asiya” prefiksi ilə qeyd olunur. Asiya handikapı olması halında\n            bahis ekspress və ya sistemə daxil edilir, sonra bunu hesablayarkən\n            mərc, uduş əmsallarından istifadə edilir, əgər əldə olunarsa\n            birrəqəmli rəqəmlərlə hesablanmışdı. Hər ikisi yarıya qalib gəlsə\n            mərclər, hesablamalarda mərc əmsalları (K) nəzərə alınır.\n            Yarım mərc qazanır, digəri isə uduzursa, əmsalların hesablanması\n            (K+1)/2 qəbul edilir. Bir yarım bahis uduzsa, lakin buna görə\n            başqa xərc, ekspress mərclərdə əmsallar 0,5 hesablanır. Əgər\n            hər iki yarım mərc itirilir, sonra bütün mərc itirilmiş hesab olunur.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            4.4. Qolların, xalların, künc zərbələrinin, sərbəst vuruşların ümumi sayına mərclər,\n            kartlar və ofis tərəfindən müəyyən edilmiş digər tədbirlər (&quot;Daha çox -\n            Daha az.\" Yuxarıdakı hadisələrin sayı ümumi olaraq təyin olunur\n            dəyər “cəmi” adlanır və ofis tərəfindən müəyyən edilir. Vuruşlar zamanı\n            cəmi, mərc qaytarılır.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.5. Müsabiqədə qalib gəlməyə və ya növbəti mərhələyə keçməyə mərclər\n            turnirlər. Əgər hər hansı bir iştirakçı müsabiqə elan edirsə\n            Səbəb yarışmaya başlaya bilmədiyim üçün buna bahis\n            İştirakçılar geri qaytarılmalıdır. İki və ya daha çox iştirakçı paylaşırsa\n            müsabiqədə qalibiyyət, onların hər biri üçün uduşlar\n            istifadə edərək hesablanmış uduş əmsalı əsasında ödənilir\n            düstur K=(Kiş-1)/N+1, burada Kiş ilkin əmsallardır\n            hər bir iştirakçıya, N müsabiqənin sayıdır\n          </span>\n        </p>\n        <p>\n          <span>\n            4.6. Müəyyən bir matç hesabı və vaxt matçına mərclər. dərəcəsi ilə\n            forması &quot;zaman uyğunluğu&quot; eyni zamanda təxmin etmək lazımdır\n            birinci hissənin və bütün matçın nəticəsi. Sırada\n            Bu nəticələri göstərmək üçün ilkin hərflərdən istifadə olunur: P - qələbə, N\n            - heç-heçə, 1-ci hissədə isə 1-ci hissənin nəticəsi müəyyənləşdi,\n            və matç ikinci yerdədir. 2-ci hissənin nəticəsi önəmli deyil\n            bu mərci hesablamaq üçün. Məsələn, matç ilə bitdi\n            hesab 1:1 və birinci\n          </span>\n        </p>\n        <p>\n          <span>\n            4.7. Turun və ya oyun gününün statistikasına mərclər. Turda olduğu halda\n            etibarsız elan edildi (4.3-cü bəndin meyarlarına uyğun olaraq) və ya ləğv edildi\n            (4.1-ci bəndin meyarlarına uyğun olaraq) ən azı bir matç, sonra mərc\n            olan mərclər istisna olmaqla, tur statistikası geri qaytarılmalıdır\n            nəticə birmənalı müəyyən edilir (məsələn, 0:0 olacaqmı\n            heç-heçə, bütün komandalar qol vuracaq və s.). Bukmeker kontorunun hüququ var\n            varsa, turun və ya oyun gününün statistikasına mərcləri qaytarmağa qərar verin\n            matçlardan birinin ləğvi ilə bağlı etibarlı məlumat\n            Tur başlamazdan əvvəl, oyunçular haqqında məlumat verilir\n            rəsmi nəticələrdə. Oyun günü üçün göstəriciləri hesablamaq\n            matçı başa vurmayan oyunçuya tennis matçları (for\n            hər hansı səbəbdən), qalan bütün setlərdə və oyunlarda məğlubiyyət sayılır. The\n            ev sahibləri komandalardır\n          </span>\n        </p>\n        <p>\n          <span>\n            4.8. Matçdakı qolların və ya xalların cüt və ya tək ümumi sayına mərclər.\n            Bahislər sətirdə göstərilmişdir. Hesab 0:0 – bərabər.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.9. Fərdi performansa və ya oyunçuların müqayisəsinə (iştirakçılar) mərclər.\n            Oyunçu sahəyə girməyibsə (iştirak etməyib), onda\n            Onun iştirakı ilə keçirilən tədbirlərə qoyulan mərclər geri qaytarılır. İştirakçılar üçün,\n            hadisəni başa çatdırmayanlar, göstəricilər hesablanır\n            çıxarılması (çıxarılması) zamanı faktiki nəticəyə görə,\n            və hesablama məqsədləri üçün belə iştirakçılar təyin edilir\n            yekun protokolda sonuncu yer. Bahislər \"olacaq\n            oyunçu üç və ya daha çox qol vurarsa, het-trik\" qazanılmış sayılır.\n            Məzənnələr \"dubl olacaqmı?\" Oyunçu qol vurarsa, qazanılmış sayılır\n            iki və ya daha çox məqsəd. Oyunçu performansına mərclərdə, a tərəfindən vurulan qollar\n            öz qapılarında oyunçu onun göstəricilərində nəzərə alınmır.\n            Komanda performansı ilə əlaqəli nisbətlərdə, bir komandanın vurduğu qollar\n            öz qolları, rəqibin vurduğu qol kimi sayılır. Hesablama xüsusiyyətləri\n            oyunçunun tennis performansına mərc edir\n          </span>\n        </p>\n        <p>\n          <span>\n            4.10. Qeyri-oynaq idman növlərində (xizək sürmə, biatlon, atletika və s.)\n            Müqayisələrdə \"Kim daha uzundur\" əgər iştirakçı (estafet yarışı üçün\n            - komanda) başladı, amma bitirmədi, sonra onlarda ona mərc edir\n            digər iştirakçı ilə müqayisədə uduzmaq. Hər iki iştirakçı getsə\n            məsafədən və ya iştirakçılardan biri başlamadı - mərclər\n          </span>\n        </p>\n        <p>\n          <span>\n            4.11. Yarımların, dövrlərin, dörddəbirlərin və s.-in nəticələrinə mərclər\n            hadisə etibarsız sayılıbsa, lakin birinci yarım (dövr və s.)\n            bitdi, sonra birinci hissəyə mərclər adi qaydada hesablanır,\n            bütövlükdə hadisəyə qoyulan mərclər geri qaytarılsa belə.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.12. Bu və ya digər hadisənin baş verəcəyi vaxta mərclər, üçün\n            məsələn, 1-ci qolun vaxtı, 1-ci kartın vaxtı, vaxtı\n            komandalardan birinə rəhbərlik etmək və s. Ordinal dəqiqəni təxmin etmək təklif olunur,\n            hadisənin baş verəcəyi. Belə tariflərin hesablanması üçün dəqiq vaxt\n            saniyələr nəzərə alınmadan müəyyən edilir. Məsələn,\n            1-ci qolun vaxtı, əgər ilk qol 00. dəqiqədə vuruldusa\n            Matçın başlamasından 10 saniyə keçmişdi – “1-ci dəqiqə”,\n            04 dəqiqə 10 saniyə – “5-ci dəqiqə”,\n          </span>\n        </p>\n        <p>\n          <span>\n            4.13. Faizlə ifadə edilən göstəricilərə mərclər (ilk xidmətin faizi,\n            topa sahib olma faizi və s.) Hesablama üçün göstəricinin qiyməti\n            rəsmi internet saytından götürülüb, tam ədədə yuvarlaqlaşdırılıb\n          </span>\n        </p>\n        <p>\n          <span>\n            4.14. Əvvəlki bir göstəricinin (p1) sayına mərclər\n            başqa bir göstəricinin başlanğıcı (p2). Məsələn, &quot;nömrə\n            ilk qoldan əvvəl hədəfə atılan atışların sayı&quot;, &quot;sayı\n            ilk kartdan əvvəl pozuntular haqqında&quot; s. Hansı hədəfə vuruldu\n            qol vuruldu və ya onlara kart verildiyi faul\n            hesab olunur. Məqsədlər və ya kartlar olmasaydı, nəticə\n            göstəricilərin ümumi sayı p1 (yəni atışların ümumi sayı).\n            hədəfdə və ya başlarda).\n          </span>\n        </p>\n        <p>\n          <span>5. Matç zamanı mərclərin qəbulu (canlı mərclər)</span>\n        </p>\n        <p>\n          <span>\n            5.1. Canlı mərclər əsas və əlavə nəticələrə qəbul edilir. sən\n            tək canlı mərclər yerləşdirə və ya onları bir ekspressdə birləşdirə bilər\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            5.2. Mərc qeydiyyatdan keçdikdən sonra qəbul edilmiş sayılır\n            server və onlayn təsdiqin verilməsi. Qəbul edilən tarif ola bilməz\n            dəyişdi. Göstərilən hallar baş verdikdə\n            “Mərclərin qəbulu üçün əsas qaydalar” bölməsində hesablamaq olar\n            əmsalları olan canlı mərc\n          </span>\n        </p>\n        <p>\n          <span>\n            5.3. Bukmeker kontor cari olan hər hansı qeyri-dəqiqliyə görə məsuliyyət daşımır\n            canlı mərclərin qəbul edildiyi matçların nəticələri. Müştərilər etməlidir\n            digər müstəqil mənbələrdən də istifadə etmək.\n            \n          </span>\n        </p>\n        <p>\n          <span>5.4. Canlı mərclər redaktə edilmir və silinmir.</span>\n        </p>\n        <p>\n          <span>\n            6. Matçların nəticələri, onların başlama tarixi və vaxtı, sırası\n            mübahisəli qərar\n          </span>\n        </p>\n        <p>\n          <span>\n            6.1. Səhv nəticəyə görə dərəcə hesablamalarına yenidən baxıla bilər\n            bukmeker kontoru tərəfindən təmin edilir. Mərcləri hesablayarkən faktiki\n            hadisələrin başlama vaxtı nəzərə alınır ki, bu da təxminən müəyyən edilir\n            idmanla məşğul olan təşkilatların rəsmi sənədləri əsasında\n            müsabiqələr, və əgər belə təsdiq edilmiş sənədlər yoxdursa, o zaman əsaslandırılır\n            idman federasiyalarının rəsmi saytlarında, idman klublarının saytlarında\n            və digər mənbələrdən idman məlumatları.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            6.2. Bukmeker şirkəti uyğunsuzluğa görə məsuliyyət daşımır\n            tarix və vaxt və hadisələrin faktiki başlanğıcı arasında. Tarix və\n            vaxt Sətirdə göstərilən hadisələrin başlanğıcı göstəricidir.\n            Mərcləri hesablayarkən, tədbirin faktiki başlama vaxtı götürülür\n            nəzərə alınır ki, bu da vəzifəli şəxs əsasında müəyyən edilir\n            sənədləri həyata keçirən təşkilat\n          </span>\n        </p>\n        <p>\n          <span>\n            6.3. Bukmeker kontoru adlardakı hər hansı qeyri-dəqiqliyə görə məsuliyyət daşımır\n            çempionatların və matçların müddəti (idman tədbirləri). The\n            sətirdə və canlı yayımda göstərilən məlumatlar indikativ xarakter daşıyır.\n            Müştərilər aydınlaşdırmaq üçün digər müstəqil məlumat mənbələrindən istifadə etməlidirlər\n            idman hadisəsi haqqında məlumat. Hadisənin nəticəsi ilə bağlı iddialar\n            varsa, tədbir bitdikdən sonra 10 gün ərzində qəbul edilir\n            təşkilat tərəfindən verilən tədbirin nəticəsi haqqında rəsmi sənədlərdir\n            müsabiqənin keçirilməsi.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            6.4. Tədbir başlayandan sonra qoyulmuş mərclər hesablanır\n            əmsallar “1” (canlı mərclər istisna olmaqla); ekspress mərclərdə Oranlar\n            belə mərclər üçün “1”-ə bərabər hesab olunur.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.5. Müştəri bir hadisəyə mərc edərsə, nəticəsi o\n            məlum idi, belə bir tarif ləğv edilə bilər. Bu halda\n            həll bukmeker şirkəti xüsusi bağlandıqdan sonra qəbul edilir\n            araşdırmalar. Belə bir dərəcə ilə bağlı bütün hərəkətlər müvəqqətidir\n            dayandırılıb.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            6.6. İştirakçı tədbir başlamazdan əvvəl döyüşməkdən imtina edərsə,\n            sonra bu iştirakçıya bütün mərclər olacaq\n          </span>\n        </p>\n        <p>\n          <span>\n            6.7. İştirakçı hər hansı bir səbəbdən (yaralanma, imtina və s.) olarsa\n            Müsabiqə əsnasında ortadan qaldırıldıqdan sonra bütün bahislər əvvələ qoyulur\n            iştirak etdiyi müsabiqənin son mərhələsinə və ya mərhələsinə başlamaq,\n            etibarlı sayılır və digər mərclər etibarsız sayılır.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            6.8. Əgər iştirakçı, komandanın üzvüdürsə (futbolçu, xokkey\n            oyunçu, basketbolçu və s.) matçda iştirak etməmiş,\n            mərclər üçün uduş əmsalının “1”-ə bərabər olduğu güman edilir\n          </span>\n        </p>\n        <p>\n          <span>\n            6.9. Əgər tennis matçında əvvəl imtina (diskvalifikasiya) baş verərsə\n            Matçın başlanğıcında, mərclər üçün qazanma əmsalları qəbul edilir\n            iştirakçının nəticəsinə mərclər istisna olmaqla, “1”ə bərabər olmalıdır\n            müsabiqədə. Tennis matçı kəsilsə, tamamlanmadı\n            eyni gün və təxirə salınmış, üzərinə qoyulan bahislər sonuna qədər qüvvədə qalır\n            bu matçın oynandığı turnir matça qədər\n            tamamlandı və ya imtina baş verdi\n          </span>\n        </p>\n        <p>\n          <span>\n            6.10. Bir tədbirdə (matç, yarış və ya döyüş) bir cüt iştirakçı varsa\n            (komandalar, idmançılar) və sonradan cütün tərkibi dəyişir,\n            onda həmin hadisəyə qoyulan bütün mərclər etibarsız olacaq.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.11. Komanda yarışlarında, bir və ya bir neçə iştirakçını əvəz edərkən\n            hər hansı bir səbəbdən komandalardan hər hansı birinin, bütün nəticəyə mərc\n            uyğunluqlar qüvvədə qalır.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            6.12. Qoşa yarışlarda, əgər cütlərin tərkibi göstərilibsə,\n            iştirakçılardan ən azı birini əvəz edərkən, qazanma əmsalları\n            mərclər üçün \"1\" bərabər olacaq. Əgər sıra deyilsə\n          </span>\n        </p>\n        <p>\n          <span>\n            6.13. “Ev sahibi” və “qonaq” anlayışlarının yer aldığı yarışlarda,\n            tədbirin keçirildiyi halda: neytral sahəyə – mərclər qalır\n            güclü; rəqib komandanın meydanında - mərclər qüvvədə qalır.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.14. “Ev sahibi” və “qonaq” anlayışları tətbiq olunmursa\n            tədbirə (məsələn, tək və qoşa idman növləri üzrə), sonra\n            tədbirin yeri dəyişdirildikdə, ona qoyulan bütün mərclər qüvvədə qalır. Komandalar\n            NBA, NHL, AHL, CHL, OHL, WHL, Şərqi Sahil Xokkey Liqası Şimali Amerika\n            birbaşa ardıcıllıqla (ev sahibləri - qonaqlar) və əksinə təşkil edilə bilər.\n            Ters tənzimləmə halında, mərclər üçün geri qaytarılma yoxdur.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            6.15. Nə zamanla klub yoldaşlıq turnirlərinin yoldaşlıq oyunlarında\n            tədbirin yeri dəyişir, ona qoyulan bütün mərclər eyni qalır\n            güc.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.16. İdman və ya ayrı-ayrı təsvirləri olmayan vəziyyətlər\n            mərclərin qəbulu və hesablanması xüsusiyyətlərinə tabedir\n            Ümumi qaydalar.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.17. Presedent olmadan mübahisəli vəziyyətlərdə, final\n            qərar bukmeker şirkəti tərəfindən verilir.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.18. Müxtəlif mənbələrdən alınan məlumatların uyğunsuzluğu halında\n            məlumat (tarix, vaxt, nəticə, komandanın adı) Bukmeker kontoru\n            şirkət tam araşdırmaya qədər uduşların ödənilməsini dayandırır\n            bu cür məlumatların həqiqiliyi. Nəticə tamamlandısa\n            rəsmi internet saytında təqdim edilən hadisə ilə fərqlənir\n            Televiziya yayımı məlumatlarını, Şirkət buraxma haqqını özündə saxlayır\n            televiziya məlumat verilişləri əsasında hesablamalar aparmaq.&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            6.19. Odds çıxış proqramında xəta aşkar edilərsə və\n            şirkət tərəfindən bu səhvin tanınması, bütün bahislər üzərinə qoyulur\n            bu hadisələr qalib sayılır və mərclər qalibiyyətlə ödənilir\n            əmsallar “1”-ə bərabərdir.\n          </span>\n        </p>\n        <p>\n          <span>7. Sides&#160;</span>\n        </p>\n        <p>\n          <span>\n            7.1. Müqavilənin bütün müddəaları, o cümlədən “biz” əvəzlikləri,\n            \"biz\", \"bizim\" və ya \"Şirkət\", birlikdə olduğu Şirkəti ifadə edir\n            müştəri 1-ci bəndinə uyğun olaraq müqavilə bağlayır\n          </span>\n        </p>\n        <p>\n          <span>8. Şərtlərin dəyişdirilməsi</span>\n        </p>\n        <p>\n          <span>\n            8.1. Bir sıra səbəblərə görə, yəni: kommersiya, hüquqi, eləcə də\n            Müştəri xidməti ilə əlaqədar səbəblərdən hər hansı birini etmə haqqımız var\n            Müqaviləyə dəyişikliklər. Müqavilənin cari müddəaları və onların\n            qüvvəyə minmə tarixləri internet saytında təqdim olunur. Müştəri şəxsi hesab edir\n            cari Müqavilə ilə tanışlığa görə məsuliyyət daşıyır.\n            U Şirkətin fəaliyyətində dəyişiklik etmək hüququ var\n            istənilən vaxt və Müştərilərə əvvəlcədən məlumat vermədən vebsayt.\n          </span>\n        </p>\n        <p>\n          <span>\n            8.2. Müqavilənin dəyişdirilmiş bəndləri ilə razılaşmadıqda,\n            Müştəri Vebsaytdan istifadəni dayandırmalıdır. Bundan sonra Vebsaytdan istifadə edin\n            Müqavilənin dəyişdirilmiş maddələrinin qüvvəyə minməsi, iradəsi\n            Müştərinin olub-olmamasından asılı olmayaraq, onun tam qəbulu kimi qəbul edilməlidir\n            müvafiq bildiriş aldı və ya dəyişikliklər haqqında öyrəndi\n            yenilənmiş Müqavilədən.\n          </span>\n        </p>\n        <p>\n          <span>9. İddia hüququ</span>\n        </p>\n        <p>\n          <span>\n            9.1. 21 yaşına çatmamış və ya yaşına çatmamış şəxslər (bundan sonra\n            qanuni iştirak üçün məcburi olan icazə verilən yaş kimi).\n            xüsusi yurisdiksiyanın qanunlarına əsasən qumarda (21 yaşdan yuxarı olduqda).\n            yaş) Vebsaytdan istifadə etmək qadağandır. istifadə\n            İcazə Verilən Yaşdan aşağı şəxslər tərəfindən vebsaytın açılması birbaşa pozuntudur\n            Sazişin. Bu baxımdan bizim hər an haqqımız var\n            Müştərinin yaşını və şəxsiyyətini təsdiq edə biləcək sənədləri tələb edin.\n            Müştəriyə onun hesabına xidmət göstərməkdən imtina edilə bilər\n            dayandırıla və ya xitam verilə bilər, mərclər və uduşlar etibarsızdır və hər hansı\n            qalan vəsait geri qaytarılmadan tutulursa, bizim tələbimizlə onlar\n            Müştərinin yaşının uyğun olduğuna dair sübut təqdim edilməməsi Məqbuldur,\n            və ya Müştərinin nail olmadığı müəyyən edildikdə\n            Məqbul yaş.&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            9.2. Bəzi yurisdiksiyalarda onlayn qumar qanunsuzdur. Qəbul etməklə\n            Müqavilə, Müştəri Şirkətin edə bilməyəcəyini başa düşür\n            qanuniliyi ilə bağlı zəmanət və ya hüquqi məsləhət vermək\n            yurisdiksiya ərazisində Veb saytdan istifadə edərək, harada\n            Müştəri yerləşir. Biz xidmətlər iddia edə bilməz\n            Vebsayt Müştərinin yurisdiksiyasının qanunlarını pozmur. The\n            müştəri öz istəyi ilə Veb-saytın xidmətlərindən istifadə edir və öhdəsinə götürür\n            tam məsuliyyət, mümkün olan hər şeyi yaxşı bilmək\n          </span>\n        </p>\n        <p>\n          <span>\n            9.3. Biz Müştəriyə xidmətlər axtarmırıq və təmin etmək niyyətində deyilik\n            yurisdiksiyasının qanunlarını pozur. Müqaviləni qəbul etməklə,\n            Müştəri Vebsaytdan istifadənin uyğun olduğunu təsdiq edir və zəmanət verir\n            ərazi yurisdiksiyasında qüvvədə olan qanun və qaydalarla.\n            Biz Vebsaytın qanunsuz istifadə xidmətlərinə görə məsuliyyət daşımırıq.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            9.4. Hüquqi səbəblərə görə biz aşağıdakılardan Müştəriləri qəbul etmirik\n            ölkələr:\n          </span>\n        </p>\n        <p>\n          <span>\n            9.4.1. Mütləq məhdudiyyət. ABŞ-dan olan müştərilər qəbul edilmir\n            Kanada, Böyük Britaniya, İspaniya, Latviya, Litva, Hollandiya,\n            Fransa, İtaliya, İsveçrə, Albaniya, Barbados, Pakistan, Suriya, Cənubi\n            Sudan, Kayman adaları, Haiti, Yamayka, Şimali Koreya, Malta və Panama.\n            Bu ölkələrin ərazisində yaşayan və ya qalan şəxslər, o\n            hesabına hesablar açmağa və ya vəsait yatırmağa icazə verilmir\n            Veb sayt. Yurisdiksiyaların siyahısı dəyişdirilə bilər və dəyişdirilə bilər\n            Şirkət tərəfindən Müştərilərə əvvəlcədən xəbərdarlıq edilmədən istehsal edilə bilər. Razısınız\n            müddət ərzində hesab açmayacaq və ya ona pul köçürməyəcəksiniz\n            yuxarıda göstərilən yurisdiksiyalardan birinin ərazisində.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            9.4.2. Qara siyahı. 9.4.1 bəndinə əlavə olaraq, bütün NetEnt oyunları qadağandır\n            aşağıdakı ölkələrdə: Əfqanıstan, Albaniya, Əlcəzair, Anqola,\n            Avstraliya, Kamboca, Ekvador, Qayana, Honq-Konq, İndoneziya, İran,\n            İraq, İsrail, Küveyt, Laos, Myanma, Namibiya, Nikaraqua, Şimali\n            Koreya, Pakistan, Panama, Papua Yeni Qvineya, Filippin, Sinqapur,\n            Cənubi Koreya, Sudan, Suriya, Tayvan, Uqanda, Yəmən, Zimbabve,\n            Belçika, Bolqarıstan, Danimarka, Estoniya, Latviya, Litva, Çexiya,\n            Meksika, Portuqaliya, Rumıniya.\n          </span>\n        </p>\n        <p>\n          <span>9.4.3. Brend oyunlar üçün məhdudiyyətlər.&#160;</span>\n        </p>\n        <p>\n          <span>\n            9.4.3.1. Oyunlar Silahlar & amp; Roses, Jimi Hendrix və Motörhead\n            aşağıdakı ölkələrdə xidmət göstərilmir: Əfqanıstan, Albaniya,\n            Əlcəzair, Anqola, Kamboca, Ekvador, Qayana, Honq Konq, İndoneziya,\n            İran, İraq, Küveyt, Laos, Myanma, Namibiya, Nikaraqua, Şimali Koreya,\n            Pakistan, Panama, Papua Yeni Qvineya, Filippin, Sinqapur, Cənubi Koreya,\n            Sudan, Suriya, Tayvan, Uqanda, Yəmən, Zimbabve, Belçika, Bolqarıstan, Kanada,\n            Danimarka, Estoniya, Fransa, İtaliya, Latviya, Litva, Meksika, Portuqaliya,\n            Rumıniya, İspaniya, Amerika Birləşmiş Ştatları, Böyük Britaniya, Avstraliya,\n            Azərbaycan, Çin, Hindistan, Malayziya, Qətər, Rusiya, Tailand, Tunis,\n            Türkiyə və Ukrayna.&#160;\n          </span>\n        </p>\n        <p>\n          <span>9.4.3.2. Oyunlar </span>Universal Canavarlar (Frankenstein, Gəlin\n          Frankenstein, Drakula, Fantomun lənəti, Qaradan gələn məxluq\n          Lagoon və Görünməz Adam\n          <span>\n            ), EKSKLÜZİVLƏ aşağıdakı ölkələrdə xidmət göstərilir: Andorra,\n            Ermənistan, Azərbaycan, Belarus, Bosniya və Herseqovina, Braziliya, Gürcüstan,\n            İslandiya, Lixtenşteyn, Moldova, Monako, Monteneqro, Norveç,\n            Rusiya, San Marino, Serbiya, İsveçrə, Ukrayna, Xorvatiya, Makedoniya,\n            Türkiyə, Avstriya, Bolqarıstan, Kipr, Finlandiya, Almaniya, Yunanıstan, Macarıstan,\n            İrlandiya, Lüksemburq, Malta, Hollandiya, Peru, Polşa, Slovakiya,\n            Sloveniya və İsveç.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            9.4.4. Birləşdirilmiş Jackpot Limitləri. Pooled cekpotlar dəstəklənmir və\n            aşağıdakı ölkələrdə mövcud olmaya bilər: Avstraliya, Azərbaycan,\n            Çin, Danimarka, Hindistan, İsrail, İtaliya, Yaponiya, Malayziya, Qətər,\n            Rusiya, İspaniya, Tayland, Tunis, Türkiyə, Birləşmiş Ərəb Əmirlikləri və\n            Ukrayna.\n          </span>\n        </p>\n        <p>\n          <span>9.5. Mərclər qəbul edilmir:</span>\n        </p>\n        <p>\n          <span>\n            9.5.1. hansı tədbirlərin iştirakçısı olan şəxslərdən\n            mərc oyunçuları (idmançılar, məşqçilər, hakimlər, klub sahibləri və ya funksionerlər və\n            nəticələrinə təsir etmək imkanı olan digər şəxslər\n            hadisə), habelə onların adından çıxış edən şəxslərdən; şəxslərdən\n            başqalarının maraqlarını təmsil edir\n          </span>\n        </p>\n        <p>\n          <span>\n            9.5.2. müqavilədə iştirak edən digər şəxslərdən\n            bukmeker ilə şirkət cari qadağandır\n          </span>\n        </p>\n        <p>\n          <span>\n            9.6. Bu Müqavilənin 9.5-ci bəndinin pozulmasına görə məsuliyyət daşıyır\n            bahisçi tərəfindən. Bu Müqavilənin pozulması halında,\n            bukmeker şirkəti istənilən uduşun ödənilməsindən imtina etmək hüququnu özündə saxlayır\n            və ya depozit edilmiş məbləğlərin qaytarılması, eləcə də hər hansı mərclərin ləğvi.\n            Bukmeker şirkəti &#160; məsuliyyət daşımır\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            müştərinin daxil olduğunu dəqiq nə vaxt bildiyinə dair\n            yuxarıda sadalanan şəxslər kateqoriyalarından biri. Bu o deməkdir ki\n            bukmeker şirkəti istənilən vaxt bu tədbirləri görmək hüququna malikdir\n            Müştərilərdən biri olduğu məlum olduqdan sonra zaman müəyyən edilmişdir\n            şəxslər.\n          </span>\n        </p>\n        <p>\n          <span>\n            9.7. Əgər mərcçi bukmeker şirkəti ilə bağlı saxtakarlıq edirsə (çox hesablı,\n            mərclərin avtomatlaşdırılması üçün proqram təminatından istifadə, arbitraj vəziyyətlərində oynamaq,\n            oyun hesab mərc etmək üçün istifadə edilmirsə, loyallıqdan sui-istifadə edin\n            proqramlar və s.), sonra bukmeker şirkəti ehtiyatları tərk edir\n            mərcləri ləğv etməklə bu cür saxtakarlığı dayandırmaq hüququ və\n            mərc iştirakçısının oyun hesabının bağlanması.\n            \n          </span>\n        </p>\n        <p>\n          <span>10. &#160; hesabının açılması</span>\n        </p>\n        <p>\n          <span>\n            10.1. Bütün əsas xidmətlərə daxil olmaq üçün Vebsaytı açmalısınız\n            hesab. Bunun üçün Müştəri “1 kliklə” qeydiyyatdan keçə bilər.\n            və ya e-poçt ünvanınızı göstərin və parol tapın,\n            daha sonra oyun profilinə daxil olmaq üçün istifadə olunacaq və həmçinin,\n            əlavə olaraq Şəxsi məlumatlar tələb olunur: ad, telefon nömrəsi və\n            doğum tarixi.&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            10.2. Müştəri qeydiyyat zamanı real e-poçt ünvanını göstərməlidir\n            prosesi həyata keçirin və ya “1 kliklə” qeydiyyat zamanı real ünvanı dəyişin.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            10.3. Məlumatın düzgünlüyünü təsdiqləmək üçün Şirkət var\n            Müştərinin şəxsiyyətini təsdiq edən sənədləri tələb etmək hüququ. Əgər\n            nədənsə Müştəri tələb olunan identifikasiyanı təqdim etmir\n            Müştərinin sənədlərini dayandırmaq və ya bloklamaq hüququna malikdir\n            lazımi məlumatları verənə qədər profil.&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            10.4. Müştəri təsdiq edir ki, Veb-saytda qeydiyyatdan keçərkən,\n            özü haqqında tam və dəqiq məlumatları göstərdi və in\n            onda hər hansı dəyişiklik baş verdikdə, Müştəri öz öhdəliyini üzərinə götürür\n            Onları dərhal profilinizə əlavə edin. əməl edilməməsi və ya\n            bu qaydaya məhəl qoymamaq tətbiq məhdudiyyətləri ilə nəticələnə bilər,\n            profilin dayandırılması və ya bloklanması, habelə ləğv edilməsi\n            ödənişlərin.\n          </span>\n        </p>\n        <p>\n          <span>\n            10.5. Qeydiyyatla bağlı hər hansı sualınız və ya probleminiz varsa\n            Vebsayt, Müştəri onlayn chat vasitəsilə dəstək xidməti ilə əlaqə saxlaya bilər\n            və ya zəng edin – 8 (800) 301-77-89 (24 saat).\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            10.6. Hər bir Müştəri Vebsaytda yalnız bir hesab aça bilər. Digər\n            Müştəri tərəfindən açılmış hesablar dublikat hesab ediləcək. bizdə var\n            belə hesabları bağlamaq və bütün əməliyyatları etibarsız hesab etmək hüququ vardır\n            dublikat hesabdan istifadə etməklə həyata keçirilir.\n          </span>\n        </p>\n        <p>\n          <span>\n            10.6.1. Bütün əmanətləri və edilən mərcləri Müştərilərə qaytarmayın\n            əsas və ehtiyat hesablar; hər kəsin uduşunun qaytarılmasını tələb etmək,\n            dublikat hesabdan istifadə zamanı alınan bonuslar və pul vəsaitləri. Müştəri\n            ilk tələbimizə uyğun olaraq onları geri qaytarmağa borcludur.&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>11. Şəxsiyyətin yoxlanılması. Qanuniləşdirmə&#160;</span>\n        </p>\n        <p>\n          <span>\n            11.1 Profilinizdə qeyd olunan ad və doğum tarixini qeyd edin\n            əsl adınıza uyğun olmalıdır.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            11.2 Qeydiyyat zamanı profilinizdə qeyd olunan ad\n            kredit kartı və ya digər ödəniş profillərindəki ada uyğun olmalıdır,\n            oyun hesabınızdan/hesabınıza vəsait artırmaq və ya çıxarmaq üçün istifadə olunur.&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            11.3 Şəxsiyyətinizi, ünvanınızı və/və ya ödəniş profilinizi təsdiq etmək üçün\n            (şəxsiyyət) biz istənilən vaxt tələb edə bilərik:&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.3.1. şəxsiyyəti təsdiq edən sənəd (o cümlədən, lakin bununla məhdudlaşmayaraq etibarlı surətlər\n            pasport/şəxsiyyət və/və ya istifadə edilmiş ödəniş kartları),\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            11.3.2. son kommunal daxil olmaqla, lakin bununla məhdudlaşmayan ünvan sübutu\n            veksellər (üç aydan çox olmayan resept), &#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            11.3.3. aidiyyəti olan hesabların vəziyyəti haqqında bankdan arayış\n            seçilmiş ödəniş üsuluna (üçdən çox deyil\n          </span>\n        </p>\n        <p>\n          <span>\n            11.4 Əgər bu sənədləri bizə təqdim etməsəniz və/yaxud biz bunu edə bilmərik\n            müəyyən edilmiş ağlabatan müddət ərzində şəxsiyyətinizi təsdiqləyin\n            tərəfimizdən, biz hüququ qoruyuruq;&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.4.1 Doğrulama uğurla başa çatana qədər Müştərinin profilini bloklayın\n            tamamlandı;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.4.2 Bütün və ya bəzi əməliyyatlarınızı ləğv etmək və profilinizi dondurmaq,\n            və/və ya profilinizi dondurun və ya bağlayın və bu Müqaviləni ləğv edin.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            11.5 Biz istənilən vaxt təhlükəsizlik yoxlamaları aparmaq hüququnu özümüzdə saxlayırıq\n            şəxsiyyətiniz, yaşınız və digər qeydiyyatınız haqqında məlumatı təsdiqləmək üçün\n            və ya Xidmətlərdən istifadənizi yoxlamaq üçün təqdim etdiyiniz ödəniş məlumatı\n            (məsələn, Qadağan olunmuş Fəaliyyətlərin qarşısını almaq üçün), uyğunluğunuz\n            bu Müqavilələrlə və maliyyə əməliyyatlarınızı yoxlayın\n            Potensial üçün xidmətlərin istifadəsi çərçivəsində edilir\n            bu Müqavilələrin pozulması.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            11.6 Siz bukmeker kontoruna hər hansı sorğu vermək hüququ verirsiniz\n            haqqında hər hansı bir məlumatı istifadə etmək və üçüncü tərəfə açıqlamaq\n            onu yoxlamaq məqsədi ilə.\n          </span>\n        </p>\n        <p>\n          <span>\n            11.7 Siz bizim sorğumuza əsasən hər hansı əlavə təmin etməyə razılaşırsınız\n            Audit təhlükəsizliyinin aparılması üçün məlumat və ya sənədlər.&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            11.8 Bu prosedur məcburi tələbdir və burada həyata keçirilir\n            mövcud qumar qaydalarına və qanuni tələblərə uyğun olaraq\n            o cümlədən çirkli pulların yuyulmasına qarşı mübarizə aparmaq\n            qeyri-standartlar haqqında məlumatlandırma haqqında Milli Əsasnamə ilə\n            əməliyyatlar və bizim daxili çirkli pulların yuyulması və qarşısının alınması\n            terrorizmin maliyyələşdirilməsi siyasəti.\n            \n          </span>\n        </p>\n        <p>\n          <span>12. İstifadəçi adı, parol və təhlükəsizlik</span>\n        </p>\n        <p>\n          <span>\n            12.1. Vebsaytda hesab açdıqdan sonra Müştəri öhdəlik götürür\n            onun parol və istifadəçi adı gizli saxlanılır və deyil\n            məlumatları üçüncü şəxslərə açıqladı. Məlumatların itirilməsi halında\n            hesaba daxil olmaq üçün lazım olduqda, onları tapa və ya bərpa edə bilərsiniz\n            \"Şifrəni bərpa et\" üzərinə klikləməklə\n          </span>\n        </p>\n        <p>\n          <span>\n            12.2. Müştəri parolun təhlükəsizliyinə görə məsuliyyət daşıyır\n            habelə onun hesabı ilə edilən hər hansı hərəkət və əməliyyatlar. Bundan əlavə,\n            nəticəsində dəyən bütün itkilərə görə Müştəri məsuliyyət daşıyır\n            onun hərəkətləri üçüncü şəxs.\n          </span>\n        </p>\n        <p>\n          <span>\n            12.3. Təhlükəsizliyin pozulması və hesaba icazəsiz giriş halında\n            Müştəri dərhal bukmeker şirkətini xəbərdar etməlidir. Əgər\n            lazım olduqda, Müştəri Şirkətə sübut təqdim etməyə borcludur\n            icazəsiz girişin baş verdiyi etibarlıdır. Bukmeker şirkəti\n            nəticəsində Müştərinin aldığı zərərə görə məsuliyyət daşımır\n            istifadəçi adı və şifrənin üçdə birinin səhv və ya ehtiyatsız istifadəsi\n            tərəf və ya hesaba icazəsiz giriş üçün.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            13. Hesaba vəsaitlərin qoyulması, yerləşdirilməsi və çıxarılması\n          </span>\n        </p>\n        <p>\n          <span>\n            13.1. Vebsaytda mərc etmək üçün Müştəri yerləşdirməlidir\n            hesabınızda müəyyən miqdarda pul.\n          </span>\n        </p>\n        <p>\n          <span>13.2. Müştəri aşağıdakıları təsdiq edir və öhdəsinə götürür:</span>\n        </p>\n        <p>\n          <span>\n            13.2.1. oyun hesabına yatırılan vəsait əldə edilməmişdir\n            qeyri-qanuni və ya qadağan olunmuş vasitələrlə;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.2.2. Müştəri tamamlanmış əməliyyatlardan imtina etməyəcək, etməyəcək\n            geri qaytarmaq üçün səbəb ola biləcək ödənişləri rədd etmək və ləğv etmək\n            pulu üçüncü tərəfə versin və qanuni məsuliyyətdən azad olunsun.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            13.3. Biz üçüncü şəxslərdən pul qəbul etmirik: dostlar, qohumlar\n            və ya tərəfdaşlar. Müştəri yalnız hesabınızdan vəsait qoymağa borcludur,\n            Müştərinin adına qeydiyyatdan keçmiş bank kartı və ya sistem.\n            Faktlar aşkar edilərsə, bu şərtin pozulması bütün uduşlar\n            müsadirə oluna bilər.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.4. Pulun geri qaytarılması üçün bank köçürməsi tələb edildiyi təqdirdə\n            onların qanuni sahibinə, bütün xərclər və komissiyalar ödənilir\n            alıcının xərci.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.5. Nağd ödənişləri qəbul etmirik. Elektron üçün istifadə edə bilərik\n            ödənişlər, o cümlədən müştərilərə daxil olan ödənişlər və ödənişlər,\n            elektron ödəniş prosessorları ilə məşğul olan müxtəlif təşkilatlar\n            və ya maliyyə institutları. Qaydalarda olduğu hallar istisna olmaqla\n            və bu qurumların şərtləri Sazişin şərtlərinə ziddir,\n            Müştəri belə qaydaları tam qəbul edir.&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            13.6. Müştəri əməliyyatlardan imtina etməməyə, ləğv etməməyə və ya ləğv etməməyə razıdır\n            hesabından istifadə etməklə həyata keçirib. Bundan əlavə, belə halların hər birində,\n            Müştəri şirkətin məbləğini qaytarmağa və ya kompensasiya etməyə borcludur\n            toplanması zamanı çəkə biləcəyimiz xərclər də daxil olmaqla yerləşdirilməmiş vəsaitlərin\n            Müştəri depozitləri.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.7. Şirkət Müştərinin hesabını bloklamaq hüququna malikdir,\n            həmçinin hər hansı bir şübhə yaranarsa ödənişləri ləğv edin və uduşları bərpa edin\n            hesabın saxta yolla doldurulduğunu bildirib. Bizim haqqımız var\n            ödəniş saxtakarlığı və qanunsuzluqlar barədə müvafiq orqanlara məlumat vermək\n            fəaliyyətləri. Kolleksiya xidmətlərindən istifadə etmək hüququmuz var\n            geri qaytarmaq üçün agentliklər. Şirkət icazəsizlərə görə məsuliyyət daşımır\n            oğurlandığı bildirilməsindən asılı olmayaraq kredit kartlarından istifadə\n            ya yox.&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            13.8. Müştərinin müsbət balansından istifadə etmək hüququmuz var\n            Müştərinin ödəməli olduğu pul məbləğini ödəmək üçün hesab\n            Şirkətlər. Xüsusilə, təkrar mərc və ya bahis hallarında, görə\n            10-cu bəndinə (\"Sözləşmə, Aldadıcı Təcrübələr, Fırıldaqçılıq\" və cinayət\n            fəaliyyət) və ya bənd 13 (“Səhvlər və çatışmazlıqlar”)&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            13.9. Müştəri oyundan tam xəbərdardır və qəbul edir\n            hesab bank hesabı deyil. Buna görə də üsullara münasibətdə\n            sığorta, doldurma, zəmanət və digər üsullar tətbiq edilmir\n            ona əmanətlərin sığortalanması sistemindən qorunma üsulları\n            və digər sığorta sistemləri. Oyun hesabındakı vəsait\n            faiz tutulmur.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.10. Müştərinin pul çıxarmaq üçün müraciət etmək hüququ var\n            hesabdan nə vaxt\n          </span>\n        </p>\n        <p>\n          <span>\n            13.10.1 Hesaba daxil olan bütün ödənişlər yoxlanılıb və\n            heç biri olmayıb\n          </span>\n        </p>\n        <p>\n          <span>\n            13.10.2. yoxlama tədbirləri lazımi qaydada həyata keçirilmişdir.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.11. Hesabdan pul vəsaitlərinin çıxarılması üçün ərizəni icra edərkən,\n            aşağıdakılar olmalıdır\n          </span>\n        </p>\n        <p>\n          <span>13.11.1. oyun profili tamamilə doldurulmalıdır;</span>\n        </p>\n        <p>\n          <span>\n            13.11.2. tələb edilən geri götürmə əməliyyatının nəticəsi olarsa\n            pul vəsaitlərinin çıxarılmasının ümumi məbləği 50.000 rubldan çoxdur. və ya ekvivalent\n            hər hansı digər valyutada məbləği, onun müəyyənləşdirilməsi həyata keçiriləcək\n            prosedur. Bunu həyata keçirmək üçün Müştəri bizə surətini və ya göndərməlidir\n            Müştərinin şəxsiyyətini müəyyənləşdirən sənədin rəqəmsal fotoşəkili.\n            Hesabınızı kredit kartı ilə doldurarkən, bir nüsxəsini göndərməlisiniz\n            Bu kartın hər iki tərəfinin şəkli. İlk altı və son dörd rəqəm,\n            CVV2 kodu gizlənə bilər;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            13.11.3. şirkət xərcləri ödəmək üçün komissiya almaq hüququna malikdir;\n            oyunda istifadə olunmayan vəsaitlərin çıxarılması ilə bağlı;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.11.4. 5000 rubla və ya ekvivalentinə qədər çəkilmə məbləği\n            digər valyutada olan məbləğ, 1-dən 60-a qədər müştərinin hesabına ödənilir\n            ərizə təqdim edildiyi andan dəqiqələr\n            ilə texniki problemlər istisna olmaqla\n          </span>\n        </p>\n        <p>\n          <span>\n            13.11.5. 5000 rubldan və ya ekvivalent məbləğdən çəkilmə məbləği\n            başqa valyutada, 5 gün ərzində müştərinin hesabına ödənilir\n            müraciət anı;\n          </span>\n        </p>\n        <p>\n          <span>\n            11/13/6. Asılı olaraq 3 iş gününə qədər digər gecikmələr mümkündür\n            bankdan və ya digər ödəniş sistemindən;\n          </span>\n        </p>\n        <p>\n          <span>\n            11/13/7. uduşları geri götürməyin digər yolları ilə ayrıca müzakirə edilir\n            Vebsayt Administrasiyası.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.12. Şirkət pul mübadiləsi xidmətləri göstərmir. bizdə var\n            belə hesabları bağlamaq hüququ və:\n          </span>\n        </p>\n        <p>\n          <span>\n            13.12.1. geri çəkdiyimiz məbləğdə komissiya tutmaq\n            oyuna cəlb edilməyən xərclər; &#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.12.2. əsas istifadə etməklə aparılan bütün əməliyyatları etibarsız hesab edir\n            və dublikat hesablar;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.12.3. Müştərilərə əsas və\n            dublikat hesablar.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.13 Pul vəsaitlərinin çıxarılmasını aktivləşdirmək üçün oyunçu yerləşdirməlidir\n            edilən hər əmanətin ən azı 100%-i məbləğində mərclər və ya ən azı istifadə edin\n            Platformamızda istənilən oyunlarda edilən hər əmanətin 100%-i (oynayın, istifadə edin).\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            13.14. Uduş məbləği 5.000.000-dan (beş milyon\n            rubl), bukmeker şirkəti gündəlik təyin etmək hüququnu özündə saxlayır\n            hər bir Müştəri üçün fərdi olaraq hesablanan pul çıxarma limiti.\n            \n          </span>\n        </p>\n        <p>\n          <span>14. Bukmeker xidmətlərinin şərtləri:</span>\n        </p>\n        <p>\n          <span>\n            14.1. Siz bütün xidmətlər və/yaxud mallar və ya digər ödənişlərə razılaşırsınız\n            Saytda sifariş etdiyiniz əlavə xidmətlər, eləcə də hamısı\n            əlavə xərclər (lazım olduqda), o cümlədən, lakin məhdudlaşdırılmadan\n            bütün növ vergilərə, rüsumlara və s. üçün tam məsuliyyət daşıyırsınız\n            bütün ödənişlərin vaxtında ödənilməsi. Provayder yalnız ödəniş xidmətləri təmin edir\n            ödəniş müəyyən edilmiş Vebsayt ölçüsündə həyata keçirilir və deyil\n            Veb saytın istifadəçisi tərəfindən ödənişə görə məsuliyyət daşıyır\n            əlavə məbləğlərdən yuxarıdır. \"Ödəniş\" düyməsini sıxdıqdan sonra,\n            ödəniş emal edilmiş hesab olunur və o, geri dönməzdir\n            yerinə yetirildi. \"Ödəniş\" düyməsini klikləməklə, bununla razılaşırsınız\n            ödənişi geri qaytara və ya onun ləğvini tələb edə bilməyəcək.\n            Saytda sifariş verməklə siz təsdiq edirsiniz və bildirirsiniz ki\n            heç bir dövlətin qanunlarını pozmur. Bundan əlavə,\n            bu qaydaların (və/və ya Şərt və müddəaların) müddəalarını qəbul etməklə,\n            Siz ödəniş kartının sahibi kimi hüququnuz olduğunu təsdiq edirsiniz\n            Website.&#160;-də təklif olunan mal və/və ya xidmətlərdən istifadə etmək\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            14.2. Bu cür xüsusi təklif edən Vebsaytın xidmətlərindən istifadə edirsinizsə\n            xidmətlər oyun xidmətləri kimi, siz qanuni olaraq məcburi təsdiqi təqdim edirsiniz\n            əldə etdiyiniz və ya artıq qanuni aşdığınız\n            istifadə etmək üçün yurisdiksiyanızda icazə verilən yetkinlik yaşı\n            Veb sayt tərəfindən təmin edilən xidmətlər.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            14.3. Vebsaytın xidmətlərindən istifadə etməyə başlamaqla siz öz öhdəliyini götürürsünüz\n            hər hansı bir ölkənin qanunlarına riayət etmək üçün hüquqi məsuliyyət\n            bu xidmətdən istifadə edildiyi yerdə və təsdiqləyin ki, ödəniş xidməti təminatçısı\n            qeyri-qanuni və ya icazəsiz oxşarlara görə heç bir məsuliyyət daşımır\n            pozulması. Veb saytın xidmətlərindən istifadə etməklə razılaşırsınız, başa düşürsünüz\n            və ödənişlərinizdən hər hansı birinin işlənməsinin həyata keçirildiyini qəbul edin\n            ödəniş təminatçısı xidmətləri tərəfindən həyata keçirilir və heç bir qanuni hüququ yoxdur\n            artıq alınmış əşyaları qaytarın. xidmətlər və/yaxud mallar və ya digər\n            ödənişin ləğvi variantları. Xidmətdən istifadəni dayandırmaq istəyirsinizsə\n            növbəti alış xidmətləriniz və/və ya mallarınız üçün siz imtina edə bilərsiniz\n            &#160; saytında Şəxsi hesabdan istifadə edərək xidmət\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            14.4. Ödəniş xidməti təminatçısı məsuliyyət daşımır\n            ödəniş kartınızla bağlı məlumatları emal etməkdən imtina/bilməmək və ya\n            emitent bankdan icazə alınmamasına görə imtinaya görə\n            ödəniş kartı kartlarınızdan istifadə edərək ödəniş edin. Ödəniş xidməti\n            provayder heç birinin keyfiyyətinə, həcminə, qiymətinə görə məsuliyyət daşımır\n            Sizə təklif olunan və ya satın aldığınız xidmət və/və ya məhsul\n            Ödəniş kartınızdan istifadə edərək sayt. İstənilən xidmət və/yaxud ödəniş etməklə\n            Veb saytın mallarına, ilk növbədə, riayət etmək məcburiyyətindəsiniz\n            Vebsaytdan istifadə qaydaları. Yalnız bunu nəzərə alın\n            ödəniş kartının sahibi kimi siz ödənişin vaxtında aparılmasına cavabdehsiniz\n            Vebsayt vasitəsilə sifariş etdiyiniz hər hansı xidmət və/və ya məhsulun və\n            bu xərclər/komissiyalarla bağlı bütün əlavə ödənişlər üçün.\n            Ödəniş xidmətinin təminatçısı yalnız ödənişin icraçısıdır\n            Vebsayt tərəfindən müəyyən edilmiş məbləğdə və heç bir məsuliyyət daşımır\n            hər hansı qiymət, ümumi qiymətlər və/və ya ümumi məbləğlər üçün.&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            14.5. Yuxarıdakılarla razılaşmamağınızla bağlı vəziyyət yaranarsa\n            şərtlərə və/və ya digər səbəblərə görə sizdən xahiş edirik ki, bunu etməkdən imtina edəsiniz\n            vaxtında ödəniş edin və zəruri hallarda Vebsaytla əlaqə saxlayın\n            birbaşa administrator/dəstək.\n          </span>\n        </p>\n        <p>\n          <span>\n            15. Söhbət, Yanlış təqdimat, Fırıldaqçılıq və cinayət fəaliyyəti&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            15.1. Şirkət bir qrup Müştəri tərəfindən mərc oynamağı tövsiyə etmir\n            bir IP ünvanı ilə və ya eyni yerli şəbəkədən\n            əvvəlcədən təsdiq kimi. Yuxarıda göstərilən addımlar sui-qəsd kimi qəbul edilə bilər,\n            saxtakarlıq, aldadıcı hərəkətlər.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            15.2. Şirkət nə vaxt olacağı ilə bağlı heç bir məsuliyyət daşımır\n            o, mərcdən xəbərdar oldu və ya sonradan müəyyən etdi\n            qaydaların pozulması ilə nəticələnmişdir. Bağlamaq hüququmuz var\n            oxşar hesablar və:&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.2.1. bütün əməliyyatları etibarsız hesab edin, hamısını müştərilərə qaytarmayın\n            digər Müştərilərlə razılaşdırılaraq edilən depozitlər və mərclər;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            15.2.2. bütün uduşların, bonusların və pul vəsaitlərinin qaytarılmasını tələb edin\n            sui-qəsd nəticəsində əldə edilmişdir. Müştəri geri qaytarmağa borcludur\n            onları bizim ilk xahişimizlə.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.3. Aşağıdakı fəaliyyətlər bu cür hərəkətlər qəti qadağandır\n            birbaşa pozuntu kimi qiymətləndiriləcək Müqavilələr:&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>15.3.1. məlumatın üçüncü tərəfə ötürülməsi;</span>\n        </p>\n        <p>\n          <span>\n            15.3.2. qeyri-qanuni fəaliyyətlər: fırıldaqçılıq, zərərli proqramların istismarı,\n            botlar və proqram səhvləri Vebsayt;&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            15.3.3. oğurlanmış, klonlanmış və ya başqa şəkildə istifadə kimi saxta fəaliyyətlər\n            hesabınızı doldurmaq üçün qeyri-qanuni əldə edilmiş kredit məlumatları və ya debet kartı;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            15.3.4. cinayət fəaliyyətlərində iştirak, çirkli pulların yuyulması və\n            iştirakın cinayətlə nəticələnə biləcəyi digər fəaliyyətlər\n            məsuliyyət;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.4. Ödənişləri dayandırmaq, ləğv etmək və ya geri götürmək hüququmuz var\n            və ya şübhələndiyimiz təqdirdə bonus fondları ilə əlaqəli uduşlar\n            Müştərinin onlardan qəsdən sui-istifadə etməsi.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            15.5. Şirkət qanunla icazə verilən və icazə verilən hər şeyi alacaq\n            saxta sui-qəsdləri istisna etmək və müəyyən etmək üçün tədbirlər və onların\n            bilavasitə iştirakçılara, habelə bu şəxslərə qarşı məcburi qaydada\n            Müvafiq tədbirlər görüləcək. Biz məsuliyyət daşımırıq\n            saxtakarlıq nəticəsində Müştərilər tərəfindən alınan itkilər və zərərlər üçün\n            fəaliyyətləri.\n          </span>\n        </p>\n        <p>\n          <span>\n            15.6. Müştərilərdən, əgər varsa, dərhal bizə məlumat vermələri tələb olunur\n            hər hansı bir Müştərinin sövdələşməyə və ya saxtakarlığa yol verdiyinə dair şübhələr yaranır\n            fəaliyyətləri. Xidmət vasitəsilə əlaqə saxlayaraq bizimlə əlaqə saxlaya bilərsiniz\n            Onlayn söhbət vasitəsilə və ya zəng etməklə vebsayt dəstəyi – 8 (800) 301-77-89\n            (24/7).&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            15.7. Müştərilərə əvvəlcədən xəbərdarlıq etmədən qadağan etmək hüququmuz var\n            Veb saytına daxil olmaq və onların hesablarını bloklamaq, əgər varsa\n            dələduzluqda şübhəli bilinirlər. Biz belə hallarda\n            geri qaytarılmalara və mövcud kompensasiya fondlarına görə məsuliyyət daşımırlar\n            belə Müştərilərin hesablarında. Bundan əlavə, bizim haqqımız var\n            qanunsuz hərəkətlər barədə hüquq-mühafizə orqanlarına məlumat vermək. Müştərilər\n            kimi araşdırmalarda bizimlə tam əməkdaşlıq etmələri tələb olunur\n            hallar.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.8. Müştərilərə xidmətlərdən və proqram təminatından istifadə etmək qadağandır\n            hər hansı bir saxtakarlıq, qeyri-qanuni əməliyyatların aparılması üçün Veb saytı təmin etmək\n            hər hansı xüsusi qanunlara uyğun hərəkətlər və əməliyyatlar\n            yurisdiksiya. Müştəri bir fakt müəyyən edildikdə və ya aşkar edildikdə\n            belə hərəkətlər edərsə, Şirkət dayandıra və ya bloklaya bilər\n            Müştərinin hesabı və orada mövcud olan pul vəsaitləri. Belədə\n            hallarda, Müştərilərin təqdim etmək hüququ yoxdur\n            iddia edir.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.9. adından oyun fəaliyyəti ilə məşğul olmaq qadağandır\n            üçüncü şəxslərin (oyun hesabının nominal sahibləri).\n          </span>\n        </p>\n        <p>\n          <span>\n            Proses baş verərsə, oyun profili dərhal bloklanır\n            xidmət əməkdaşının təhlükəsizliyi tərəfindən oyun profilinin yoxlanması\n            yoxlanılan şəxsin olmadığı müəyyən ediləcək\n            idman mərc oyunları sahəsində kifayət qədər biliyə malikdir.&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>16.&#160; saytında digər qadağan olunmuş hərəkətlər</span>\n        </p>\n        <p>\n          <span>\n            16.1. Təcavüzkar və ya təhqiredici şəkildə istifadə etmək qadağandır\n            ünsiyyət, söyüş, təhdid və hər hansı zorakı hərəkətlərdən istifadə etmək\n            Şirkətin işçilərinə və digər Müştərilərinə qarşı. Müştəri uğursuz olarsa\n            Bu bənd qaydalarına riayət etmək üçün Şirkət dayandırmaq hüququna malikdir\n            bu Müştəri ilə əlaqə saxlayın və ya daxil olan tətbiqi tərk edin\n            nəzərə alınmadan.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            16.2. Sayta müəyyən miqdarda məlumat yükləmək qadağandır\n            Vebsaytın işində fasilələrə səbəb ola biləcək və\n            resursun fəaliyyətinə təsir edə biləcək hər hansı digər hərəkətləri həyata keçirmək.\n            Bu halda bu viruslar, zərərli proqramlar, kütləvi göndərişlər və spam deməkdir\n            - yuxarıda göstərilənlərin hamısı qəti qadağandır. Bundan əlavə, Müştərilər\n            saytında yerləşdirilən məlumatı silmək, dəyişdirmək və ya redaktə etmək qadağandır\n            Vebsayt.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            16.3. Müştərilər Vebsaytdan yalnız əyləncə üçün istifadə edə bilərlər\n            məqsədləri. Website.&#160;-in tam və ya qismən surətini çıxarmaq qadağandır\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            16.4. Müştərilər Vebsaytı sındırmağa yönəlmiş hərəkətlərə yol verməməyi öhdələrinə götürürlər\n            təhlükəsizlik sistemləri, məxfi məlumatlara qeyri-qanuni giriş əldə etmək və ya\n            DDoS hücumları. Müştərilərə münasibətdə, pozmaqda şübhəli bilinir\n            bu qayda müvafiq tədbirlərə tabe olacaq: tam\n            Vebsayta girişin qadağan edilməsi və profilin bloklanması. Bundan əlavə,\n            haqqında məsul orqanlara məlumat vermək hüququmuz var\n            Müştərinin qanunsuz hərəkətləri.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            16.5. Biz baş verə biləcək hər hansı itki və ya ziyana görə məsuliyyət daşımırıq\n            səbəb olan texniki nasazlıqlara görə Müştərilərimizə və ya üçüncü tərəflərə\n            virus hücumları və ya vebsayta yönəlmiş digər zərərli hərəkətlərlə.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            16.6. Profilinin ötürülməsi və satılması qəti qadağandır\n            bir Müştəridən digərinə.&#160;\n          </span>\n        </p>\n        <p>\n          <span>17. &#160; Sazişinin ləğvi şərtləri və proseduru</span>\n        </p>\n        <p>\n          <span>\n            17.1. Şirkət Müştərinin profilini silmək hüququna malikdir (kimi\n            həmçinin onun adı və şifrəsi) aşağıdakıları əvvəlcədən xəbərdar etmədən\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.1. Şirkət hamıya xidmət göstərməyi dayandırmaq qərarına gəlib\n            və ya Müştərilərin müəyyən hissəsi;&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.2. Müştərinin profili bir növ əvvəlki ilə əlaqəlidir\n            silinmiş profil;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.3. Müştərinin profili hazırda bloklanmış profillə əlaqələndirilir\n            bir profil, bu halda Şirkət bağlamaq hüququna malikdir\n            rabitə növündən asılı olmayaraq profil və tamamilə\n            bu profillərin etimadnaməsini bloklayın. Başqa cür nəzərdə tutulmadıqda\n            Müqavilədə Müştərinin profilində yerləşən vəsait geri qaytarılacaq\n            ərizəni doldurduqdan dərhal sonra müəyyən müddət ərzində ona\n            və Müştərinin borclu olduğu məbləğin tutulması\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.4. Müştəri cinayət sui-qəsdində iştirak edir\n            və ya sındırmağa cəhd\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.5. Müştəri proqram təminatının Veb saytına və ya cəhdlərinə müdaxilə edir\n            hər hansı digər fəaliyyəti həyata keçirmək;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.6. Müştəri profilindən ola biləcək məqsədlər üçün istifadə edir\n            hər hansı xüsusi yurisdiksiyanın qanunvericiliyinə görə qeyri-qanuni hesab edilir;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.7. Müştəri Vebsaytda təhqiredici məlumatları dərc edir\n            və ya alçaldıcı xarakter daşıyır.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.2. Şirkət Müştərinin profilini bağlamaq hüququna malikdir və ya\n            müvafiq məktub göndərməklə Müqavilənin qüvvəsini ləğv etmək\n            əlaqə məlumatında göstərilən e-poçt ünvanına bildiriş. halda\n            bəndində göstərilən hallar istisna olmaqla, bizim tərəfimizdən bu cür hərəkətlərdən\n            bənd 15 (“Sözləşmə, Aldatma, Fırıldaqçılıq və cinayət fəaliyyəti”)\n            və bu Müqavilənin 22 (\"Şərtlərin pozulması\"), Şirkət\n            hesabdan Müştəridən vəsaiti qaytarmağa borcludur. Əgər hər hansısa\n            Müştəri ilə əlaqə saxlaya bilməməyimizə görə, vəsait müvəqqəti olacaq\n            bukmeker kontorunun və ya nəzarət orqanının hesabına köçürülür.\n            \n          </span>\n        </p>\n        <p>\n          <span>18. Vebsaytda edilən dəyişikliklər</span>\n        </p>\n        <p>\n          <span>\n            18.1. İstənilən vaxt öz mülahizəmizə uyğun olaraq etmək hüququmuz var\n            üçün Veb saytında təklif olunan xidmətlərə dəyişikliklər və ya əlavələr\n            saxlamaq və yeniləmək məqsədi daşıyır\n          </span>\n        </p>\n        <p>\n          <span>19. Sistem xətaları</span>\n        </p>\n        <p>\n          <span>\n            19.1. Oyun zamanı Vebsaytda nasazlıq olarsa,\n            Şirkət vəziyyəti mümkün qədər tez düzəltməyə çalışacaq.\n            Biz informasiya mediasında yaranan problemlərə görə məsuliyyət daşıyırıq\n            avadanlıqların istismarı nəticəsində yaranan texnologiyalar,\n            Müştərilər tərəfindən Vebsayta daxil olmaq üçün, eləcə də uğursuzluqlar üçün istifadə olunur\n            İnternet provayderlərinin işi.\n          </span>\n        </p>\n        <p>\n          <span>20. Səhvlər və çatışmazlıqlar</span>\n        </p>\n        <p>\n          <span>\n            20.1. Şirkət istənilən mərcləri məhdudlaşdırmaq və ya ləğv etmək hüququna malikdir.\n          </span>\n        </p>\n        <p>\n          <span>\n            20.2. Müştəri nəticədə onun hesabına daxil olan vəsaitdən istifadə etdikdə\n            bir səhvə görə, mərc etmək və oyunda iştirak etmək üçün biz ləğv edə bilərik\n            bu cür mərclər və onlardan alınan hər hansı uduşlar kömək edir. Əgər nağd ödəniş olarsa\n            belə dərəcələrlə fondlar edilmişsə, o zaman bu məbləğlər nəzərə alınmalıdır\n            Etibarlı idarəetmədə Müştəriyə təhvil verilmiş, Müştəri borcludur\n            ilk tələbimizə görə onları geri qaytarmaq.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            20.3. Şirkət və xidmət təminatçıları dəymiş ziyana görə məsuliyyət daşımır\n            o cümlədən Müştərinin səhvləri nəticəsində uduşların itirilməsi\n            tərəfdən və ya bizim tərəfdən.\n          </span>\n        </p>\n        <p>\n          <span>\n            20.4. Şirkət, onun distribyutorları, filialları, lisenziya sahibləri, törəmə müəssisələri\n            müəssisələr, eləcə də işçilər və rəhbərlər daşımır\n            ələ keçirmə nəticəsində yaranan hər hansı itki və ya zərər üçün məsuliyyət\n            və ya sui-istifadə &#160;\n          </span>\n        </p>\n        <p>\n          <span>İnternet vasitəsilə ötürülən məlumat.&#160;</span>\n        </p>\n        <p>\n          <span>21. Məsuliyyətimizin məhdudlaşdırılması&#160;</span>\n        </p>\n        <p>\n          <span>\n            21.1. Müştəri müstəqil olaraq xidmətlərdən istifadə etmək qərarına gəlir.\n            və hər hansı hərəkətlər və onların nəticələri şəxsi nəticədir\n            Müştərinin seçimi, öz mülahizəsinə görə, öz qorxusu və riski ilə edilir.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            21.2. Saytın fəaliyyəti müvafiq olaraq həyata keçirilir\n            bu Sazişin bəndləri ilə. Şirkət heç bir şey vermir\n            Vebsaytla bağlı əlavə zəmanətlər və ya nümayəndəliklər\n            və onun üzərində təklif olunan xidmətlər və bununla da onun məsuliyyətini istisna edir\n            (qanunla nəzərdə tutulmuş həddə) nəzərdə tutulan bütün təminatlara münasibətdə.&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            21.3. Biz hüquq pozuntularına, səhlənkarlığa, itkilərə və məsuliyyət daşımırıq\n            bu anda proqnozlaşdırıla bilməyən zərərlər.&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            21.4. Şirkət resursların məzmununa görə məsuliyyət daşımır,\n            vebsayt vasitəsilə əldə edilə bilər.\n          </span>\n        </p>\n        <p>\n          <span>22. Şərtlərin pozulması</span>\n        </p>\n        <p>\n          <span>\n            22.1. Müştəri qoruduğu itkiləri tam kompensasiya etməyə razılaşır\n            və Şirkətin, onun tərəfdaşlarının, işçilərinin və maraqlarını müdafiə etmək\n            yaranan hər hansı iddialardan, öhdəliklərdən, xərclərdən, itkilərdən və məsrəflərdən direktorlar\n            səbəbi: &#160;\n          </span>\n        </p>\n        <p>\n          <span>22.1.1. Müştəri tərəfindən Müqavilənin şərtlərinin pozulması;</span>\n        </p>\n        <p>\n          <span>22.1.2. Sifarişçi tərəfindən qanunların və üçüncü şəxslərin hüquqlarının pozulması;</span>\n        </p>\n        <p>\n          <span>\n            22.1.3. hər hansı digər şəxs tərəfindən Vebsayt xidmətlərinə giriş əldə etdikdə\n            Müştərinin identifikasiya məlumatlarından onun icazəsi və ya icazəsi olmadan istifadə etmək\n            ona və ya;\n          </span>\n        </p>\n        <p>\n          <span>22.1.4. bu yolla əldə edilən uduşların mənimsənilməsi.</span>\n        </p>\n        <p>\n          <span>\n            22.2. Müştəri Müqavilənin şərtlərini pozarsa, bizdə\n            sağ:\n          </span>\n        </p>\n        <p>\n          <span>\n            22.2.1. Müştəriyə öz hərəkətləri ilə şərtləri pozduğunu bildirmək\n            Müqavilənin və dərhal ləğv edilməsini tələb etmək qadağandır\n            hərəkətlər;\n          </span>\n        </p>\n        <p>\n          <span>22.2.2. Müştərinin hesabını dayandırın;&#160;</span>\n        </p>\n        <p>\n          <span>\n            22.2.3. əvvəlcədən xəbərdarlıq etmədən Müştərinin hesabını bloklamaq;\n          </span>\n        </p>\n        <p>\n          <span>\n            22.2.4. Müştərinin hesabından ödənişlərin məbləğini bərpa etmək,\n            nəticəsində əldə edilən uduşlar və ya bonuslar\n          </span>\n        </p>\n        <p>\n          <span>\n            22.3. İstifadəçi adınızı və parolunuzu ləğv etmək hüququmuz var\n            Müştəri hər hansı bəndinə əməl etmədikdə\n          </span>\n        </p>\n        <p>\n          <span>23. Əqli mülkiyyət hüquqları</span>\n        </p>\n        <p>\n          <span>\n            23.1. Vebsaytdakı bütün məzmun müəllif hüquqlarına və digərlərinə tabedir\n            Şirkətə məxsus mülkiyyət hüquqları. Bütün yüklənə bilən və çap olunan materiallar\n            Vebsaytda mövcud olanlar yalnız bir kompüter üçün yüklənə bilər. Çap\n            bu materiallardan yalnız şəxsi və qeyri-kommersiya məqsədləri üçün icazə verilir\n            istifadə edin.\n          </span>\n        </p>\n        <p>\n          <span>\n            23.2. Vebsaytdan istifadə Müştəriyə heç bir hüquq vermir\n            Şirkətə və ya üçüncü tərəfə məxsus olan əqli mülkiyyətə.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            23.3. Ticarət nişanının hər hansı istifadəsi və ya təkrar istehsalı qadağandır. markalar,\n            əmtəə nişanları, loqolar və digər reklam materialları, təqdim olunur\n            Şirkətin müvafiq razılığı olmadan vebsayt.\n          </span>\n        </p>\n        <p>\n          <span>\n            23.4. Müştəri hər hansı zərər, xərc və ya xərclərə görə məsuliyyət daşıyacaq\n            qadağan olunmuş fəaliyyətlə məşğul olması nəticəsində yaranmışdır.\n            Müştərilər xəbərdar olduqları təqdirdə dərhal Şirkəti xəbərdar etməlidirlər\n            qadağan edilmiş hər hansı bir fəaliyyətin həyata keçirilməsini və lazım olan hər şeyi təmin edir\n            şirkətin edə biləcəyi araşdırmanın aparılmasına köməklik\n            verilən məlumatları nəzərə almaqla həyata keçirir.\n          </span>\n        </p>\n        <p>\n          <span>24. Müştərilərin şəxsi məlumatları</span>\n        </p>\n        <p>\n          <span>\n            24.1. Biz qoruma tələblərinə əməl etməyə borcluyuq\n            Şirkətin şəxsi məlumatlardan istifadə etdiyi formada fərdi məlumatların\n            istifadəçinin Vebsayta daxil olması nəticəsində toplanmışdır.\n            Şirkət emal öhdəliklərini ən ciddi şəkildə qəbul edir\n            Müştərilərimizin şəxsi məlumatları. Şirkət şəxsi emal edir\n            tam uyğunluq məxfilik siyasətində Müştərilər tərəfindən təmin edilən məlumatlar.\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            24.2. Şəxsi məlumatları təqdim etməklə, Müştərilər razılaşırlar ki, Şirkət\n            müəyyən edilmiş məqsədlər üçün şəxsi məlumatları emal etmək hüququna malikdir\n            Müqavilədə və ya tənzimləyici və qanuni&#160;-ə riayət etmək\n            \n          </span>\n        </p>\n        <p>\n          <span>öhdəliklər.</span>\n        </p>\n        <p>\n          <span>\n            24.3. Məxfilik siyasətinə uyğun olaraq, açıqlamamağı öhdəmizə götürürük\n            və Müştərilərimizin şəxsi məlumatlarını üçüncü tərəflərə ötürməmək,\n            informasiya emalı sistemləri və işçilər istisna olmaqla\n            zəruri hallarda ondan yalnız təmin etmək məqsədilə istifadə edə bilən\n            daha keyfiyyətli xidmətlər. 24.4. Biz bütün yazışmaların surətlərini saxlayırıq\n            Müştərilərdən alınan bütün məlumatları dəqiq qeyd etmək.\n            \n          </span>\n        </p>\n        <p>\n          <span>25. Vebsaytda kukilərdən istifadə</span>\n        </p>\n        <p>\n          <span>\n            25.1. Vebsaytın funksionallığını təmin etmək üçün kukilərdən istifadə edirik. \"Cookie\" dir\n            istifadəçinin yaddaşında saxlanılan kiçik ölçülü xüsusi mətn faylı\n            Veb saytı ziyarət edərkən kompüterimizi onun vasitəsilə tanıya bilərik\n            xüsusi istifadəçilər Vebsayta yenidən daxil olduqda. Əlavə məlumat\n            kukilərə nəzarət və silmək haqqında vebsaytda tapa bilərsiniz:\n            www.aboutcookies.org. Nəzərə alın ki, kukilər fayllarımızı silə bilər\n            Vebsaytın bəzi bölmələrinə və funksiyalarına girişi bloklamaq.\n            \n            \n          </span>\n        </p>\n        <p>\n          <span>26. Şikayətlər və bildirişlər</span>\n        </p>\n        <p>\n          <span>\n            26.1. İşlə bağlı hər hansı bir şikayət və ya iddia yaranarsa, Vebsayt,\n            ilk növbədə, iddianızı onlayn söhbət vasitəsilə dəstəyə göndərməlisiniz\n            Şirkət vebsaytı vasitəsilə (Şirkətin 24 saat dəstək telefonu\n            nömrə 8 (800) 301-77-89) və ya şirkətin e-poçt ünvanına\n            - support@imbalance.click.&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            26.2. Müştəri mübahisənin qeydinin üzərində saxlanması ilə razılaşır\n            server, iddiaya baxılarkən sübut kimi istifadə edilə bilər.\n            \n          </span>\n        </p>\n        <p>\n          <span>27. Mübahisələrin həlli qaydası</span>\n        </p>\n        <p>\n          <span>\n            27.1. Oyunçu istənilən vəziyyətə meydan oxuya bilər. Şirkət hərtərəfli\n            təmin edildiyi halda bütün mübahisəli məsələləri obyektiv şəkildə nəzərdən keçirir\n            konkret məlumat - faktlar və arqumentlər. Mübahisəli məlumatlar,\n            faktların və arqumentlərin tətbiqi ilə yazılı şəkildə təqdim edilməlidir\n            Şirkətin veb-saytı vasitəsilə onlayn söhbət vasitəsilə (tel. gecə-gündüz).\n            Şirkətin dəstəyi – 8(800)301-77-89) və ya e-poçt ünvanında\n            Şirkətin dəstək xidməti security@imbalance.click-dir. B 14 ərzində\n            şikayət məktubunun və ya sorğunun alındığı tarixdən günlər\n            yoxlanılacaq və nəticə barədə Müştəriyə məlumat veriləcək\n            cavab məktubunda nəzərə alınmalıdır. Lazım gələrsə əlavə\n            Yoxlamalar, Şirkət yoxlama müddətini uzatma hüququna malikdir\n            ərizə alındığı tarixdən 30 gün müddətində. ildə\n            məktubun mətni Hər hansı bir söyüşdən istifadə etmək qadağandır\n            mehriban təhqirlər və yalan məlumat.&#160;\n          </span>\n        </p>\n        <p>\n          <span>28. Fors-major hallar&#160;</span>\n        </p>\n        <p>\n          <span>\n            28.1. Şirkət gecikmələrə və ya yerinə yetirilməməsinə görə məsuliyyət daşımır\n            Müqavilədə sadalanan öhdəliklər, əgər onlar fors-major hallar nəticəsində yaranıbsa\n            təbii fəlakətləri başa düşmək lazım olan şərtlər,\n            müharibələr, vətəndaş iğtişaşları, əmək mübahisələri, kommunal xidmətlərdə fasilələr,\n            DDoS hücumları və ya İnternetə səbəb ola biləcək digər hücumlar\n            Veb-saytın fəaliyyətinə mənfi təsir.&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            28.2. Fors-major hallar dövründə\n            Veb-saytın fəaliyyəti dayandırılmış hesab olunur və bu müddət ərzində\n            Bu müddət ərzində icrasında bir möhlət var\n            öhdəliklər. Şirkət əlində olan bütün vasitələrdən istifadə etməyi öhdəsinə götürür\n            öhdəliklərinizi tam yerinə yetirməyə imkan verən həllər axtarmaq\n            Müştərilərə, fors-major halların sonuna qədər.&#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>29. İmtina &#160;</span>\n        </p>\n        <p>\n          <span>\n            29.1. Müştərinin hər hansı öhdəliyi yerinə yetirməsini təmin edə bilməsək\n            yoxsa özümüz heç birindən faydalana bilməyəcəyik\n            hüququmuz olan vasitələr, o zaman şərh edilməyəcəkdir\n            bu vasitələrdən imtina etmək və ya Müştərini azad etmək üçün səbəb kimi\n            öhdəlikləri yerinə yetirmək.\n          </span>\n        </p>\n        <p>\n          <span>30. &#160; müqaviləsinin bölünməsi</span>\n        </p>\n        <p>\n          <span>\n            30.1. Müqavilənin hər hansı bəndi etibarsız olarsa, qeyri-legitimdir\n            və ya hüquqi qüvvəsini itirdikdə, bu müddəa ləğv edilir\n            Müqavilənin tam olaraq qalan hissəsi öz hüquqi qüvvəsini saxlayacaqdır.\n            Belə hallarda etibarsız sayılan hissə dəyişdiriləcək\n            yenilənmiş standartlara uyğun olaraq\n            \n          </span>\n        </p>\n        <p>\n          <span>31. Links&#160;</span>\n        </p>\n        <p>\n          <span>\n            31.1. Vebsaytda digər mənbələrə keçidlər ola bilər\n            bizim nəzarətimizdən kənarda. Başqalarının məzmununa görə məsuliyyət daşımırıq\n            saytlar, onların sahiblərinin hərəkətləri və ya hərəkətsizliyi və məzmunu üçün\n            üçüncü tərəf reklamları və sponsorluqları. Digər saytlara hiperlinklər\n            yalnız məlumat məqsədləri üçün verilir. məqsədləri. Müştərilər\n            riski öz üzərlərinə götürərək istifadə edin.&#160;\n          </span>\n        </p>\n        <p>\n          <span>32. Bonus promosyonları&#160;</span>\n        </p>\n        <p>\n          <span>\n            32.1. Artan mərc (mərc) yalnız nağd bonuslar üzrə müəyyən edilir\n            və yalnız bonus məbləğinə aiddir. Əgər bonus faizdirsə\n            əmanətdən sonra mərc faiz məbləğinə tətbiq edilir. mərc\n            ölçüsü həyata keçirilən bonus təşviqindən asılıdır. və quraşdırılır\n            &#160; saytı tərəfindən\n          </span>\n        </p>\n        <p>\n          <span>\n            32.2. Nağd bonusu yalnız tam rol oynadığı halda çıxara bilərsiniz. &#160;\n            \n          </span>\n        </p>\n        <p>\n          <span>\n            Qeydiyyat üçün və ya digər hallarda pul bonusları hesablanarkən,\n            bonus aldıqdan sonra Müştərinin əmanət qoyması tələb olunmur\n            vəsait balansı, bonus hesablamasının çıxarılması mümkün deyil\n            ilk depozitə qədər.\n          </span>\n        </p>\n      </div>\n";
